import { component$, useSignal } from "@qwik.dev/core";

export type WorkspacePreviewTab =
  | "personas"
  | "rubric"
  | "comments"
  | "citations"
  | "history";

export interface WorkspacePreviewProps {
  /** Which board tab the right rail opens on. Defaults to "personas". */
  initialTab?: WorkspacePreviewTab;
  /** Which folio the manuscript opens on. Defaults to the first folio. */
  initialFolioId?: string;
  /** Whether the left drawer starts open. Defaults to true. */
  drawerOpen?: boolean;
  /** Whether the right board starts open. Defaults to true. */
  panelOpen?: boolean;
}

/**
 * A clickable mock of the writer's room: the Drawer of folios on the left,
 * the manuscript in the centre, and the Editorial Board (Cast, Rubric,
 * Marginalia, Apparatus, Versions) on the right. Every tab, folio, persona,
 * and rail toggle works — all against canned data, with no providers and no
 * network — so the landing page and Storybook show the room working, not a
 * picture of it.
 */
const panelTabs: Array<{
