 @import "tailwindcss";

 /*
  * TWYNE — The Editorial Room
  * ─────────────────────────────────────────────────────────────
  * Design language: a 1955 magazine bullpen filtered through
  * Wes Anderson's "The French Dispatch."  Newsprint paper,
  * editorial vermilion, periwinkle and sage departmental
  * accents, hot-press serif headlines, manuscript-grade body.
  * ─────────────────────────────────────────────────────────────
  */

 @theme {
   /* ── Paper & Ink ─────────────────────────────────────── */
   --color-paper: #f4ecd8; /* aged newsprint cream */
   --color-paper-2: #ebe1c9; /* deeper paper, sidebars */
   --color-paper-3: #ddd0b1; /* paper rule */
   --color-paper-soft: #faf3df; /* highlight paper */
   --color-ink: #1f1b16; /* near-black brown */
   --color-ink-light: #4a3f33; /* secondary ink */
   --color-ink-muted: #8a7e6c; /* tertiary, set in old gravure */
   --color-editor-bg: #fbf6e7; /* manuscript page */
   --color-editor-line: #efe6cb; /* manuscript ledger line */

   /* ── Departmental Accents (color-coded sections) ─────── */
   --color-vermilion: #c1272d; /* Penguin Classics red, masthead */
   --color-vermilion-2: #9c1a1f; /* deeper vermilion */
   --color-periwinkle: #5c6bc0; /* periwinkle, departmental */
   --color-sage: #8a9a5b; /* cabinet sage */
   --color-mustard: #d4a017; /* color rule, badges */
   --color-blush: #e8a598; /* salmon, soft accents */
   --color-cobalt: #2c4a7c; /* deep ocean, callouts */
   --color-writer-note: #7f4560; /* aubergine pencil, never a persona */

   /* legacy "brand" mapped to vermilion for compat */
   --color-brand: #c1272d;
   --color-brand-light: #d65157;
   --color-brand-dark: #9c1a1f;

   /* legacy "surface" mapped to paper for compat */
   --color-surface: #f4ecd8;
   --color-surface-2: #ebe1c9;
   --color-surface-3: #ddd0b1;

   /* ── Status colors (kept, but recalibrated for paper) ── */
   --color-accent-green: #5b7a3a;
   --color-accent-amber: #b8860b;
   --color-accent-red: #b3261e;
   --color-accent-blue: #2c4a7c;

   /* ── Cast colors (the persona portraits) ─────────────── */
   --color-persona-devil: #c1272d; /* vermilion */
   --color-persona-angel: #8a9a5b; /* sage */
   --color-persona-scholar: #5c6bc0; /* periwinkle */
   --color-persona-editor: #d4a017; /* mustard */
   --color-persona-reader: #2c4a7c; /* cobalt */

   /* ── Type stack ──────────────────────────────────────── */
   --font-display: "Libre Baskerville", "Playfair Display", Georgia, serif;
   --font-serif: "Lora", "Crimson Pro", Georgia, "Times New Roman", serif;
   --font-sans: "DM Sans", "Inter", system-ui, sans-serif;
   --font-mono: "JetBrains Mono", "Fira Code", monospace;
   --font-typewriter: "Special Elite", "Courier New", monospace;
 }

 /* ── Semantic z-scale ────────────────────────────────────── */
 :root {
   --z-dropdown: 30;
   --z-sticky: 20;
   --z-overlay: 40;
   --z-modal: 50;
   --z-toast: 60;
 }

 /* ─────────────────────────────────────────────────────────────
  * Tokens referenced across the app that had no definition — they
  * were resolving to `unset`. Aliases, so they follow the theme.
  * ───────────────────────────────────────────────────────────── */
 :root {
   --color-accent: var(--color-vermilion);
   --color-rule: var(--color-paper-3);
   --color-crimson: var(--color-vermilion-2);
 }

 /* Qwik Router 2 wraps client-side navigation in the browser View Transition
  * API. Keep the room steady while the next page arrives like a fresh sheet. */
 @media (prefers-reduced-motion: no-preference) {
   ::view-transition-old(root) {
     animation: 120ms ease-in both twyne-page-out;
   }

   ::view-transition-new(root) {
     animation: 220ms cubic-bezier(0.22, 1, 0.36, 1) both twyne-page-in;
   }

   @keyframes twyne-page-out {
     to {
       opacity: 0;
       transform: translateY(-0.2rem);
     }
   }

   @keyframes twyne-page-in {
     from {
       opacity: 0;
       transform: translateY(0.35rem);
     }
   }
 }

 @media (prefers-reduced-motion: reduce) {
   ::view-transition-old(root),
   ::view-transition-new(root) {
     animation: none;
   }
 }

 /* Narration follows the prose without disturbing its Markdown structure. */
 ::highlight(twyne-speech-sentence) {
   background-color: color-mix(in srgb, var(--color-mustard) 20%, transparent);
 }

 ::highlight(twyne-speech-word) {
   color: var(--color-ink);
   background-color: color-mix(
     in srgb,
     var(--color-vermilion) 26%,
     var(--color-paper)
   );
   text-decoration: underline;
   text-decoration-color: var(--color-vermilion);
   text-decoration-thickness: 2px;
   text-underline-offset: 0.16em;
 }

 [data-speech-active="playing"],
 [data-speech-active="paused"] {
   cursor: text;
 }

 [data-speech-active="loading"] {
   cursor: progress;
 }

 [data-speech-active].is-speech-seeking {
   cursor: ew-resize;
   user-select: none;
 }

 /* ─────────────────────────────────────────────────────────────
  * Document colors — the text and highlight swatches in
  * `palette.ts`, which named these custom properties without any
  * of them ever being defined.
  *
  * Literal, and deliberately outside the theme blocks. These are
  * colors the writer applies to their prose; they get written into
  * the document as hex and have to render identically in an export
  * that has no stylesheet. A theme may re-ink the room, never the
  * manuscript.
  * ───────────────────────────────────────────────────────────── */
 :root {
   --color-text-olive: #556134;
   --color-text-periwinkle: #454f9e;
   --color-text-amber: #7a5a07;
   --color-text-sienna: #964f40;
   --color-highlight-butter: #fbeaa8;
   --color-highlight-rose: #f8d3d4;
   --color-highlight-sky: #cfe0f2;
   --color-highlight-mint: #d5e6c4;
   --color-highlight-lilac: #dcdff4;
   --color-highlight-peach: #fadfd5;
 }

 /* ─────────────────────────────────────────────────────────────
  * Texture tokens
  *
  * The letterpress surfaces — paper grain, foxing, the `.folio`
  * emboss, `.ink-bleed`'s halo — used to hard-code `rgba(31,27,22,…)`
  * ink and `rgba(255,255,255,…)` highlights. Baked that way they
  * invert wrongly on any other ground: a white inset sheen on dark
  * paper reads as a scratch. Expressed against the palette instead,
  * every texture follows the active theme.
  * ───────────────────────────────────────────────────────────── */
 :root {
   /* Paper tooth. Its own tokens so a preset can flatten it entirely. */
   --grain-1: color-mix(in srgb, var(--color-ink) 2.5%, transparent);
   --grain-2: color-mix(in srgb, var(--color-ink) 2%, transparent);
   --grain-3: color-mix(in srgb, var(--color-ink) 1.5%, transparent);
   /* Base colors the textures are mixed from, never used at full strength. */
   --emboss: #ffffff;
   --foxing-base: #7a5426;
   /*
    * The color shadows are cast in. On paper this is just the ink, but a
    * shadow always darkens — on a dark preset, mixing from ink would make
    * every drop shadow glow. Kept separate so presets can say so.
    */
   --shade: var(--color-ink);
 }

 /* ─────────────────────────────────────────────────────────────
  * Themes
  *
  * Each block redefines only the core palette; everything else is
  * expressed against it, so a preset switch is one attribute flip
  * on <html>. Writers may override the eight core tokens inline on
  * top of any preset — see `src/utils/theme.ts`.
  *
  * `system` is resolved to a concrete preset by the bootstrap
  * script before first paint, so no preset block is needed for it.
  * ───────────────────────────────────────────────────────────── */

 /* Foolscap — cool grey-white, the yellow taken out. */
 [data-theme="foolscap"] {
   --color-paper: #eef0f1;
   --color-paper-2: #e3e6e8;
   --color-paper-3: #c9ced2;
   --color-paper-soft: #f7f8f9;
   --color-ink: #1c2024;
   --color-ink-light: #3f464d;
   --color-ink-muted: #69727a;
   --color-editor-bg: #f9fafb;
   --color-editor-line: #e6e9eb;
   --color-vermilion: #9b4a52;
   --color-vermilion-2: #7d353d;
   --color-mustard: #9a7b2e;
   --color-surface: #eef0f1;
   --color-surface-2: #e3e6e8;
   --color-surface-3: #c9ced2;
   --color-brand: #9b4a52;
   --color-brand-light: #b76a72;
   --color-brand-dark: #7d353d;
   /* No newsprint browning on a cool ground — foxing goes grey. */
   --foxing-base: #6b727a;
 }

 /* Broadsheet — near-white, maximum contrast, minimum tint. */
 [data-theme="broadsheet"] {
   --color-paper: #ffffff;
   --color-paper-2: #f4f4f4;
   --color-paper-3: #c4c4c4;
   --color-paper-soft: #fafafa;
   --color-ink: #111111;
   --color-ink-light: #333333;
   --color-ink-muted: #5c5c5c;
   --color-editor-bg: #ffffff;
   --color-editor-line: #ececec;
   --color-vermilion: #b3121a;
   --color-vermilion-2: #8c0d14;
   --color-surface: #ffffff;
   --color-surface-2: #f4f4f4;
   --color-surface-3: #c4c4c4;
   --color-brand: #b3121a;
   --color-brand-light: #d43c43;
   --color-brand-dark: #8c0d14;
   /* Deliberately flat: the point of this preset is an untinted page. */
   --grain-1: transparent;
   --grain-2: transparent;
   --grain-3: transparent;
   --foxing-base: transparent;
 }

 /* Nightpress — the composing room after hours. */
 [data-theme="nightpress"] {
   --color-paper: #191714;
   --color-paper-2: #211e1a;
   --color-paper-3: #3b3630;
   --color-paper-soft: #252119;
   --color-ink: #ece4d4;
   --color-ink-light: #c4bbab;
   --color-ink-muted: #8e8577;
   --color-editor-bg: #201d18;
   --color-editor-line: #2e2a23;
   --color-vermilion: #e2686c;
   --color-vermilion-2: #c14d52;
   --color-periwinkle: #8b97dc;
   --color-sage: #a8b775;
   --color-mustard: #e0b545;
   --color-blush: #e8a598;
   --color-cobalt: #7396c9;
   --color-writer-note: #d99ab0;
   --color-accent-green: #8fb069;
   --color-accent-amber: #d6a53a;
   --color-accent-red: #e2686c;
   --color-accent-blue: #7396c9;
   --color-surface: #191714;
   --color-surface-2: #211e1a;
   --color-surface-3: #3b3630;
   --color-brand: #e2686c;
   --color-brand-light: #ef8b8e;
   --color-brand-dark: #c14d52;
   --color-persona-devil: #e2686c;
   --color-persona-angel: #a8b775;
   --color-persona-scholar: #8b97dc;
   --color-persona-editor: #e0b545;
   --color-persona-reader: #7396c9;
   /*
    * Every texture is mixed from `--color-ink`, which is now the *light*
    * value — so grain and drop shadows would glow instead of darken. Point
    * them at black, and turn the white letterpress emboss into a faint rule
    * highlight, which is what a raised edge looks like on a dark ground.
    */
   --grain-1: color-mix(in srgb, #000000 18%, transparent);
   --grain-2: color-mix(in srgb, #000000 14%, transparent);
   --grain-3: color-mix(in srgb, #000000 10%, transparent);
   --emboss: var(--color-paper-3);
   --foxing-base: #c99a5b;
   --shade: #000000;
 }

 /* ── Page foundation ─────────────────────────────────────── */
 * {
   scrollbar-width: thin;
   scrollbar-color: var(--color-paper-3) transparent;
 }

 body {
   font-family: var(--font-sans);
   color: var(--color-ink);
   background-color: var(--color-paper);
   /* Subtle paper grain — barely-there noise to give the surface tooth */
   background-image:
     radial-gradient(circle at 25% 35%, var(--grain-1) 0, transparent 1px),
     radial-gradient(circle at 75% 65%, var(--grain-2) 0, transparent 1px),
     radial-gradient(circle at 45% 85%, var(--grain-3) 0, transparent 1px);
   background-size:
     7px 7px,
     11px 11px,
     13px 13px;
   font-feature-settings:
     "kern",
     "liga",
     "onum" 1;
 }

 /* ── Page margin guides ─────────────────────────────────────────────
  * Faint vermilion rules marking where the live margins sit, the way Word
  * and Google Docs show the header/footer and side margins. They track the
  * same --doc-pad-* custom properties that drive the page padding, so moving
  * the layout sliders moves the guides. Painted as the page's own background
  * so they always sit behind the text without any z-index juggling. */
 .page-canvas.show-margin-guides {
   --guide: color-mix(in srgb, var(--color-vermilion) 28%, transparent);
   background-image:
     linear-gradient(var(--guide), var(--guide)),
     linear-gradient(var(--guide), var(--guide)),
     linear-gradient(var(--guide), var(--guide)),
     linear-gradient(var(--guide), var(--guide));
   background-repeat: no-repeat;
   background-size:
     1px 100%,
     1px 100%,
     100% 1px,
     100% 1px;
   background-position:
     left var(--doc-pad-left, 3rem) top 0,
     right var(--doc-pad-right, 3rem) top 0,
     left 0 top var(--doc-pad-y, 2.5rem),
     left 0 bottom var(--doc-pad-bottom, 4rem);
 }

 /* ── Paginated canvas ───────────────────────────────────────────────
  * The document is one continuous ProseMirror; the pagination extension
  * inserts invisible spacers so that every page's content top lands on a
  * uniform grid, and everything below draws the furniture that implies.
  *
  * Nothing here may set `counter-reset` or `contain` inside .ProseMirror:
  * endnote numbering is a CSS counter scoped to that single element, and a
  * new counter scope would silently renumber every footnote in the folio. */

 /* The spacer that makes the page gap. Its height is set inline by the
  * engine and must not be overridable — it is the one number the whole
  * grid depends on. */
 .twyne-page-spacer {
   display: block;
   width: 100%;
   pointer-events: none;
   user-select: none;
 }

 .twyne-page-chrome {
   transition: opacity 0.3s ease;
 }
 .twyne-page-chrome.zen {
   opacity: 0.25;
 }

 /* One sheet. The canvas is transparent and the sheets carry the paper, so
  * the gap between them shows the desk underneath. */
 .twyne-page-sheet {
   background: var(--color-paper);
   border: 1px solid var(--color-paper-3);
   box-shadow:
     0 1px 0 color-mix(in srgb, var(--shade) 4%, transparent),
     0 18px 34px -22px color-mix(in srgb, var(--shade) 35%, transparent);
 }

 .page-canvas.is-paginated {
   background: transparent;
 }

 .twyne-page-running-header {
   display: flex;
   align-items: baseline;
   justify-content: space-between;
   gap: 1rem;
   font-family: var(--font-typewriter);
   font-size: 0.62rem;
   letter-spacing: 0.16em;
   text-transform: uppercase;
   color: var(--color-ink-muted);
   border-bottom: 1px solid var(--color-paper-3);
   padding-bottom: 0.3rem;
   white-space: nowrap;
   overflow: hidden;
 }
 .twyne-page-header-title {
   overflow: hidden;
   text-overflow: ellipsis;
 }

 .twyne-page-running-footer {
   display: grid;
   grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
   align-items: center;
   gap: 1rem;
   font-family: var(--font-typewriter);
   font-size: 0.68rem;
   letter-spacing: 0.12em;
   color: var(--color-ink-muted);
 }

 .twyne-page-footer-text {
   min-width: 0;
   overflow: hidden;
   white-space: nowrap;
 }

 .twyne-page-number {
   text-align: center;
   font-family: var(--font-typewriter);
   font-size: 0.68rem;
   letter-spacing: 0.12em;
   color: var(--color-ink-muted);
   font-variant-numeric: tabular-nums;
 }

 /* A manual page break. The node itself is invisible and weightless — the
  * engine gives it zero height — so the visible mark is drawn on the spacer
  * that opens the page, i.e. in the gap where it belongs rather than
  * hanging at the top of the following sheet. */
 .twyne-page-break {
   height: 0;
   margin: 0;
   padding: 0;
   border: 0;
 }
 .twyne-page-spacer[data-forced="true"] {
   position: relative;
 }
 .twyne-page-spacer[data-forced="true"]::after {
   content: "page break";
   position: absolute;
   left: 50%;
   top: 50%;
   transform: translate(-50%, -50%);
   font-family: var(--font-typewriter);
   font-size: 0.55rem;
   letter-spacing: 0.2em;
   text-transform: uppercase;
   color: var(--color-ink-muted);
   background: var(--color-editor-bg);
   padding: 0 0.5rem;
   z-index: 2;
 }

 /* A plate can never be taller than the page it sits on. Without this an
  * oversized image bleeds through the gap and under the page number — the
  * one case where a decoration-based engine has no better answer. */
 .page-canvas.is-paginated .twyne-editor .ProseMirror img,
 .twyne-editor.is-paginated .ProseMirror img {
   max-height: var(--page-content-h, none);
   object-fit: contain;
 }

 /* Blocks the engine could not fit on one page. Flagged rather than hidden:
  * the writer should be able to see that a table is overflowing. */
 .twyne-editor .ProseMirror [data-overflows-page] {
   box-shadow: inset 3px 0 0 var(--color-mustard);
 }

 /* An empty paginated document still shows a whole sheet, rather than a
  * page frame with 60vh of prose area inside it. */
 .page-canvas.is-paginated .ProseMirror {
   min-height: var(--page-content-h, 60vh);
 }

 /* Load-bearing for pagination: a remote collaborator's caret must never be
  * taller than the line box it sits in, or every page break in the document
  * shifts for everyone else in the session. See remote-cursors.ts. */
 .remote-cursor {
   max-height: 1.4em;
 }

 /* ── Colour swatches ────────────────────────────────────────────────
  * Shared by the colour picker and the persona editor. Lived inline in
  * routes/personas until the picker needed the same affordance; the
  * aria-pressed selected state is the convention across this codebase's
  * toggles, so the styling follows the semantics rather than a class. */
 .swatch {
   width: 1.4rem;
   height: 1.4rem;
   border-radius: 999px;
   border: 2px solid transparent;
   box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--shade) 14%, transparent);
   cursor: pointer;
   transition:
     transform 0.1s,
     border-color 0.1s;
 }
 .swatch:hover {
   transform: scale(1.08);
 }
 .swatch[aria-pressed="true"] {
   border-color: var(--color-ink);
   transform: scale(1.1);
 }

 /* ── Layout margin sliders ──────────────────────────────────────── */
 .margin-slider {
   -webkit-appearance: none;
   appearance: none;
   width: 100%;
   height: 2px;
   background: var(--color-paper-3);
   border-radius: 2px;
   outline: none;
   cursor: pointer;
 }

 .margin-slider::-webkit-slider-thumb {
   -webkit-appearance: none;
   appearance: none;
   width: 12px;
   height: 12px;
   border-radius: 50%;
   background: var(--color-vermilion);
   border: none;
   cursor: pointer;
 }

 .margin-slider::-moz-range-thumb {
   width: 12px;
   height: 12px;
   border-radius: 50%;
   background: var(--color-vermilion);
   border: none;
   cursor: pointer;
 }

 /* ── Editorial chrome utilities ──────────────────────────── */
 .masthead-rule {
   position: relative;
 }
 .masthead-rule::before,
 .masthead-rule::after {
   content: "";
   display: block;
   height: 1px;
   background: var(--color-ink);
 }
 .masthead-rule::before {
   margin-bottom: 4px;
 }
 .masthead-rule::after {
   margin-top: 4px;
   height: 3px;
 }

 .dept-label {
   font-family: var(--font-typewriter);
   font-size: 0.625rem;
   letter-spacing: 0.32em;
   text-transform: uppercase;
   color: var(--color-ink-muted);
 }

 .ornament-divider {
   display: flex;
   align-items: center;
   gap: 0.75rem;
   color: var(--color-ink-muted);
   font-family: var(--font-display);
   font-size: 0.875rem;
 }
 .ornament-divider::before,
 .ornament-divider::after {
   content: "";
   flex: 1;
   height: 1px;
   background: var(--color-paper-3);
 }

 /* Stamped, rubber-stamp aesthetic for completed states */
 .stamp {
   display: inline-block;
   padding: 0.3rem 0.7rem;
   border: 2px solid var(--color-vermilion);
   color: var(--color-vermilion);
   font-family: var(--font-typewriter);
   font-size: 0.6875rem;
   letter-spacing: 0.22em;
   text-transform: uppercase;
   transform: rotate(-3deg);
   background: color-mix(in srgb, var(--color-vermilion) 4%, transparent);
   border-radius: 2px;
 }

 /* Index card surface */
 .index-card {
   background: var(--color-paper-soft);
   background-image: repeating-linear-gradient(
     to bottom,
     transparent 0,
     transparent 27px,
     color-mix(in srgb, var(--color-periwinkle) 18%, transparent) 27px,
     color-mix(in srgb, var(--color-periwinkle) 18%, transparent) 28px
   );
   border: 1px solid var(--color-paper-3);
   box-shadow:
     0 1px 0 color-mix(in srgb, var(--shade) 4%, transparent),
     0 6px 14px -10px color-mix(in srgb, var(--shade) 18%, transparent);
   position: relative;
 }
 .index-card::before {
   /* the red top margin of an index card */
   content: "";
   position: absolute;
   top: 24px;
   left: 0;
   right: 0;
   height: 1px;
   background: var(--color-vermilion);
   opacity: 0.55;
 }

 /* The editor drawer carries the latest per-folio dossier as a filed sheet,
    distinct from the generic index-card treatment it replaced. */
 .filed-dossier-paper {
   border: 1px solid var(--color-ink-light);
   background: var(--color-paper-soft);
   box-shadow: 3px 4px 0 color-mix(in srgb, var(--color-ink) 10%, transparent);
   animation: filed-dossier-arrive 260ms cubic-bezier(0.16, 1, 0.3, 1) both;
 }

 .filed-dossier-paper::after {
   content: "";
   position: absolute;
   right: -1px;
   bottom: -1px;
   width: 1.1rem;
   height: 1.1rem;
   border-top: 1px solid var(--color-paper-3);
   border-left: 1px solid var(--color-paper-3);
   background: var(--color-paper-2);
   clip-path: polygon(100% 0, 0 100%, 100% 100%);
 }

 .filed-dossier-paper__tab {
   position: absolute;
   top: -1px;
   left: 0.75rem;
   padding: 0.22rem 0.55rem 0.28rem;
   border-right: 1px solid var(--color-ink-light);
   border-bottom: 1px solid var(--color-ink-light);
   border-left: 1px solid var(--color-ink-light);
   background: color-mix(in srgb, var(--color-mustard) 18%, var(--color-paper));
   color: var(--color-ink);
   font-family: var(--font-typewriter);
   font-size: 0.56rem;
   letter-spacing: 0.15em;
   text-transform: uppercase;
 }

 @keyframes filed-dossier-arrive {
   from {
     opacity: 0;
     transform: translateX(-0.45rem);
   }
   to {
     opacity: 1;
     transform: translateX(0);
   }
 }

 /* Dossier folder edge */
 .folio {
   background: var(--color-paper-soft);
   border: 1px solid var(--color-paper-3);
   box-shadow:
     0 1px 0 color-mix(in srgb, var(--emboss) 60%, transparent) inset,
     0 14px 32px -22px color-mix(in srgb, var(--shade) 40%, transparent),
     0 2px 0 color-mix(in srgb, var(--shade) 5%, transparent);
 }

 /* ── Drop caret and gap cursor ────────────────────────────
    Where a dragged selection will land, and where the caret sits between two
    block nodes. Both extensions ship enabled via StarterKit but neither draws
    anything useful on its own: prosemirror-gapcursor has no styles at all
    without its stylesheet, and the drop caret defaults to a 1px hairline in the
    body text colour. Vermilion matches the editorial marks elsewhere in the
    manuscript, so the insertion point reads as an instruction rather than
    as part of the prose. */
 .twyne-editor .twyne-dropcursor {
   background-color: var(--color-vermilion);
   border-radius: 1px;
   box-shadow: 0 0 0 1px
     color-mix(in srgb, var(--color-vermilion) 25%, transparent);
 }

 .twyne-editor .ProseMirror-gapcursor {
   display: none;
   pointer-events: none;
   position: absolute;
 }

 .twyne-editor .ProseMirror-gapcursor::after {
   content: "";
   display: block;
   position: absolute;
   top: -2px;
   width: 1.25rem;
   border-top: 2px solid var(--color-vermilion);
   animation: twyne-gapcursor-blink 1.1s steps(2, start) infinite;
 }

 @keyframes twyne-gapcursor-blink {
   to {
     visibility: hidden;
   }
 }

 @media (prefers-reduced-motion: reduce) {
   .twyne-editor .ProseMirror-gapcursor::after {
     animation: none;
   }
 }

 .twyne-editor .ProseMirror-focused .ProseMirror-gapcursor,
 .twyne-editor .ProseMirror-gapcursor:focus {
   display: block;
 }

 /* ── Tiptap manuscript page ──────────────────────────────── */
 .twyne-editor .ProseMirror {
   outline: none;
   min-height: 60vh;
   font-family: var(--font-serif);
   font-size: 1.125rem;
   line-height: 1.8;
   color: var(--color-ink);
   font-feature-settings:
     "kern",
     "liga",
     "onum" 1;
 }

 .twyne-editor .ProseMirror p {
   margin-bottom: 0.45em;
   text-align: justify;
   hyphens: auto;
   -webkit-hyphens: auto;
 }

 /* Drop cap on the very first paragraph — the magazine touch.
  *
  * `::first-letter` beats the inline `font-family` / `font-size` that the
  * type controls write onto the surrounding span, so anything hard-coded
  * here is a rule the writer cannot override. Setting a manuscript in
  * Special Elite used to leave its most prominent glyph in the display face.
  *
  * `font-family: inherit` puts the letter back under the writer's control.
  * The size stays proportional — a drop cap that ignored the type scale
  * would be worse — but it is bounded: 4.2em of 36pt is ~200px, which
  * overflows the sheet. The cap sits just above 4.2em of the default 18px
  * body, so the house look is unchanged until the writer goes large. */
 .twyne-editor .ProseMirror > p:first-of-type::first-letter {
   font-family: inherit;
   font-weight: 700;
   font-size: min(4.2em, 5rem);
   float: left;
   line-height: 0.85;
   margin: 0.08em 0.12em -0.05em 0;
   color: var(--color-vermilion);
 }

 .twyne-editor .ProseMirror h1 {
   font-family: var(--font-display);
   font-size: 2.5rem;
   font-weight: 700;
   letter-spacing: -0.01em;
   margin-top: 1.2em;
   margin-bottom: 0.45em;
   line-height: 1.1;
   color: var(--color-ink);
   text-align: center;
 }

 .twyne-editor .ProseMirror h1::after {
   content: "✦";
   display: block;
   text-align: center;
   color: var(--color-vermilion);
   font-size: 1rem;
   margin-top: 0.3em;
   letter-spacing: 0.5em;
 }

 .twyne-editor .ProseMirror h2 {
   font-family: var(--font-display);
   font-size: 1.5rem;
   font-weight: 600;
   margin-top: 1.5em;
   margin-bottom: 0.4em;
   line-height: 1.25;
   color: var(--color-ink);
 }

 .twyne-editor .ProseMirror h3 {
   font-family: var(--font-sans);
   font-size: 0.75rem;
   letter-spacing: 0.32em;
   text-transform: uppercase;
   font-weight: 700;
   margin-top: 1.6em;
   margin-bottom: 0.4em;
   color: var(--color-vermilion);
 }

 .twyne-editor .ProseMirror blockquote {
   border-left: 3px solid var(--color-vermilion);
   padding: 0.4em 1.25em;
   margin: 1.2em 0 1.2em 0;
   color: var(--color-ink-light);
   font-family: var(--font-display);
   font-style: italic;
   font-size: 1.25em;
   line-height: 1.55;
 }

 .twyne-editor .ProseMirror a,
 .twyne-editor .ProseMirror a.editor-link {
   color: var(--color-cobalt);
   text-decoration-line: underline;
   text-decoration-style: solid;
   text-decoration-thickness: 2px;
   text-decoration-color: color-mix(
     in srgb,
     var(--color-cobalt) 55%,
     transparent
   );
   text-underline-offset: 0.14em;
   text-decoration-skip-ink: none;
   background: linear-gradient(
     transparent 68%,
     color-mix(in srgb, var(--color-cobalt) 12%, transparent) 68%
   );
   cursor: pointer;
   transition:
     color 120ms ease,
     text-decoration-color 120ms ease,
     background 120ms ease;
 }

 .twyne-editor .ProseMirror a:hover,
 .twyne-editor .ProseMirror a.editor-link:hover,
 .twyne-editor .ProseMirror a:focus-visible,
 .twyne-editor .ProseMirror a.editor-link:focus-visible {
   color: var(--color-vermilion);
   text-decoration-color: var(--color-vermilion);
   background: linear-gradient(
     transparent 58%,
     color-mix(in srgb, var(--color-vermilion) 16%, transparent) 58%
   );
 }

 /* Checklists — task list with editorial checkboxes */
 .twyne-editor .ProseMirror ul.twyne-task-list,
 .twyne-editor .ProseMirror ul[data-type="taskList"] {
   list-style: none;
   padding-left: 0.2em;
 }
 .twyne-editor .ProseMirror ul[data-type="taskList"] li {
   display: flex;
   align-items: flex-start;
   gap: 0.55em;
   margin: 0.25em 0;
 }
 .twyne-editor .ProseMirror ul[data-type="taskList"] li > label {
   display: grid;
   width: 1.5rem;
   min-width: 1.5rem;
   min-height: 1.5rem;
   margin-top: 0.08em;
   place-items: center;
   user-select: none;
 }
 .twyne-editor
   .ProseMirror
   ul[data-type="taskList"]
   li
   > label
   input[type="checkbox"] {
   appearance: none;
   width: 1.125rem;
   height: 1.125rem;
   border: 1.5px solid var(--color-ink-muted);
   border-radius: 3px;
   background: var(--color-paper);
   cursor: pointer;
   position: relative;
   transition:
     background 0.12s ease,
     border-color 0.12s ease;
 }
 .twyne-editor
   .ProseMirror
   ul[data-type="taskList"]
   li
   > label
   input[type="checkbox"]:hover {
   border-color: var(--color-vermilion);
 }
 .twyne-editor
   .ProseMirror
   ul[data-type="taskList"]
   li
   > label
   input[type="checkbox"]:focus-visible {
   outline: 2px solid var(--color-vermilion);
   outline-offset: 2px;
 }
 .twyne-editor
   .ProseMirror
   ul[data-type="taskList"]
   li
   > label
   input[type="checkbox"]:checked {
   background: var(--color-vermilion);
   border-color: var(--color-vermilion);
 }
 .twyne-editor
   .ProseMirror
   ul[data-type="taskList"]
   li
   > label
   input[type="checkbox"]:checked::after {
   content: "✓";
   position: absolute;
   inset: 0;
   display: flex;
   align-items: center;
   justify-content: center;
   font-size: 0.8em;
   color: var(--color-paper);
 }
 .twyne-editor .ProseMirror ul[data-type="taskList"] li > div {
   flex: 1;
 }
 .twyne-editor
   .ProseMirror
   ul[data-type="taskList"]
   li[data-checked="true"]
   > div {
   color: var(--color-ink-muted);
   text-decoration: line-through;
 }

 .twyne-editor .ProseMirror code {
   font-family: var(--font-mono);
   background: var(--color-paper-2);
   padding: 0.15em 0.4em;
   border-radius: 2px;
   font-size: 0.88em;
 }

 .twyne-editor .ProseMirror pre {
   background: var(--color-ink);
   color: var(--color-paper);
   padding: 1em 1.25em;
   border-radius: 2px;
   overflow-x: auto;
   border-left: 4px solid var(--color-mustard);
 }

 .twyne-editor .ProseMirror pre code {
   background: none;
   padding: 0;
   font-size: 0.875rem;
 }

 .twyne-editor .ProseMirror img {
   max-width: 100%;
   border: 6px solid white;
   box-shadow:
     0 1px 0 var(--color-paper-3),
     0 18px 30px -18px color-mix(in srgb, var(--shade) 45%, transparent);
   margin: 1.4em auto;
   display: block;
 }

 .twyne-editor .ProseMirror .twyne-image-node {
   margin-block: 1.4em;
 }

 .twyne-editor .ProseMirror .twyne-image-node img {
   margin: 0;
 }

 .twyne-editor .ProseMirror .twyne-image-caption {
   margin-top: 0.45rem;
   color: var(--color-ink-muted);
   font-family: var(--font-sans);
   font-size: 0.78rem;
   line-height: 1.4;
   text-align: center;
 }

 .twyne-editor .ProseMirror img.ProseMirror-selectednode,
 .twyne-editor .ProseMirror .twyne-image-node.ProseMirror-selectednode {
   outline: 2px solid var(--color-vermilion);
 }

 .twyne-editor .ProseMirror table {
   border-collapse: collapse;
   /* table-layout: fixed is required for Tiptap's column-resize handles to
    * actually resize columns — without it the <colgroup> widths it writes are
    * ignored and dragging the handle does nothing. */
   table-layout: fixed;
   width: 100%;
   margin: 1em 0;
   font-family: var(--font-sans);
   font-size: 0.95rem;
   overflow: hidden;
 }

 /* Honour the per-column widths Tiptap stores in the generated <colgroup>. */
 .twyne-editor .ProseMirror table col {
   min-width: 3rem;
 }

 .twyne-editor .tableWrapper {
   margin: 1em 0;
   overflow-x: auto;
 }

 .twyne-editor .ProseMirror table td,
 .twyne-editor .ProseMirror table th {
   border: 1px solid var(--color-paper-3);
   padding: 0.55em 0.8em;
   text-align: left;
   min-width: 7rem;
   position: relative;
   vertical-align: top;
 }

 .twyne-editor .ProseMirror table th {
   background: var(--color-paper-2);
   font-weight: 700;
   font-family: var(--font-typewriter);
   font-size: 0.7rem;
   letter-spacing: 0.18em;
   text-transform: uppercase;
 }

 .twyne-editor .ProseMirror table caption {
   caption-side: top;
   padding: 0.35rem 0 0.6rem;
   text-align: left;
   font-family: var(--font-serif);
   font-size: 0.82rem;
   font-style: italic;
   color: var(--color-ink-muted);
 }

 .twyne-editor .ProseMirror table[data-table-style="plain"] td,
 .twyne-editor .ProseMirror table[data-table-style="plain"] th {
   border-color: transparent;
 }

 .twyne-editor .ProseMirror table[data-table-style="grid"] td,
 .twyne-editor .ProseMirror table[data-table-style="grid"] th {
   border: 1px solid var(--color-paper-3);
 }

 .twyne-editor
   .ProseMirror
   table[data-table-style="banded-rows"]
   tbody
   tr:nth-child(even)
   > td {
   background: var(--color-paper-soft);
 }

 .twyne-editor .ProseMirror table[data-table-style="minimal"] td,
 .twyne-editor .ProseMirror table[data-table-style="minimal"] th {
   border-width: 0 0 1px;
   border-color: var(--color-paper-3);
 }

 .twyne-editor .ProseMirror table .selectedCell::after {
   content: "";
   position: absolute;
   inset: 0;
   background: color-mix(in srgb, var(--color-vermilion) 8%, transparent);
   pointer-events: none;
 }

 .twyne-editor .ProseMirror table .column-resize-handle {
   position: absolute;
   top: 0;
   right: -1px;
   bottom: -1px;
   width: 3px;
   background: var(--color-vermilion);
   opacity: 0.55;
   pointer-events: none;
 }

 .twyne-editor .ProseMirror.resize-cursor {
   cursor: col-resize;
 }

 .twyne-editor .ProseMirror.row-resize-cursor {
   cursor: row-resize;
 }

 .twyne-editor .ProseMirror table .row-resize-handle {
   position: absolute;
   left: -1px;
   right: -1px;
   bottom: -3px;
   height: 6px;
   background: var(--color-vermilion);
   opacity: 0;
   pointer-events: auto;
   cursor: row-resize;
   z-index: 2;
 }

 .twyne-editor .ProseMirror table .row-resize-handle:hover,
 .twyne-editor .ProseMirror table .row-resize-handle:active {
   opacity: 0.55;
 }

 .twyne-editor .ProseMirror table .row-resize-handle::after {
   content: "";
   position: absolute;
   inset: -4px 0;
 }

 /* The default highlighter: a marker stroke across the lower two-fifths,
  * rather than a filled block. */
 .twyne-editor .ProseMirror mark {
   background: linear-gradient(
     transparent 60%,
     color-mix(in srgb, var(--color-mustard) 45%, transparent) 60%
   );
   padding: 0;
   border-radius: 0;
 }

 /* A chosen colour arrives as an inline `background-color`, which cannot beat
  * the gradient above — `background-image` is a different longhand, so the
  * stroke would paint straight over the writer's colour and every highlight
  * would look mustard. Clearing the image lets the inline colour through. */
 .twyne-editor .ProseMirror mark[data-color] {
   background-image: none;
 }

 /* Superscript and subscript, pinned so they cannot grow the line box.
  * Load-bearing for pagination: a raised character that makes its line taller
  * changes every page break below it. The same reasoning as .remote-cursor. */
 .twyne-editor .ProseMirror sup,
 .twyne-editor .ProseMirror sub {
   font-size: 0.72em;
   line-height: 0;
   position: relative;
   vertical-align: baseline;
 }
 .twyne-editor .ProseMirror sup {
   top: -0.45em;
 }
 .twyne-editor .ProseMirror sub {
   bottom: -0.22em;
 }

 /* Alignment set on the paragraph wins over the manuscript's default
  * justification — otherwise choosing "left" would appear to do nothing. */
 .twyne-editor .ProseMirror p[style*="text-align"] {
   hyphens: manual;
   -webkit-hyphens: manual;
 }

 .twyne-editor .ProseMirror hr {
   border: none;
   text-align: center;
   margin: 2em 0;
 }
 .twyne-editor .ProseMirror hr::before {
   content: "❦";
   color: var(--color-vermilion);
   font-size: 1.1rem;
   letter-spacing: 0.5em;
 }

 .twyne-editor .ProseMirror .is-editor-empty:first-child::before {
   content: attr(data-placeholder);
   float: left;
   color: var(--color-ink-muted);
   pointer-events: none;
   height: 0;
   font-style: italic;
   font-family: var(--font-display);
 }

 /* Citation: a hot-pencil underline */
 .twyne-editor .ProseMirror .citation-mark {
   background-color: color-mix(
     in srgb,
     var(--color-periwinkle) 10%,
     transparent
   );
   border-bottom: 2px dotted var(--color-periwinkle);
   cursor: pointer;
 }

 /* ── Selection actions ────────────────────────────────────────────
    A small piece of editorial furniture attached to the selected passage.
    It keeps research, marginalia, and persona requests in the manuscript. */
 .selection-actions {
   position: fixed;
   z-index: var(--z-dropdown);
   width: max-content;
   max-width: min(32rem, calc(100vw - 1rem));
   border: 1px solid color-mix(in srgb, var(--color-ink-muted) 52%, transparent);
   background: color-mix(in srgb, var(--color-paper) 91%, transparent);
   box-shadow: 0 0.65rem 1.8rem rgba(32, 25, 16, 0.2);
   backdrop-filter: blur(14px) saturate(0.9);
   color: var(--color-ink);
 }
 .selection-actions--above {
   transform: translate(-50%, -100%);
 }
 .selection-actions--below {
   transform: translateX(-50%);
 }
 .selection-actions__quote {
   overflow: hidden;
   padding: 0.35rem 0.55rem;
   border-bottom: 1px solid
     color-mix(in srgb, var(--color-paper-3) 76%, transparent);
   color: var(--color-ink-muted);
   font-family: var(--font-serif);
   font-size: 0.72rem;
   font-style: italic;
   text-overflow: ellipsis;
   white-space: nowrap;
 }
 .selection-actions__row {
   display: flex;
   align-items: stretch;
 }
 .selection-actions__row > button {
   padding: 0.5rem 0.58rem;
   border-right: 1px solid
     color-mix(in srgb, var(--color-paper-3) 72%, transparent);
   color: var(--color-ink-light);
   font-family: var(--font-typewriter);
   font-size: 0.65rem;
   letter-spacing: 0.08em;
   text-transform: uppercase;
   white-space: nowrap;
 }
 .selection-actions__row > button:hover:not(:disabled) {
   color: var(--color-vermilion);
   background: color-mix(in srgb, var(--color-vermilion) 6%, transparent);
 }
 .selection-actions__row > button:disabled {
   cursor: wait;
   opacity: 0.45;
 }
 .selection-actions__row > .selection-actions__close {
   border-right: 0;
   color: var(--color-ink-muted);
   font-size: 0.8rem;
 }
 .selection-actions__error {
   padding: 0.4rem 0.55rem;
   border-top: 1px solid
     color-mix(in srgb, var(--color-vermilion) 30%, transparent);
   color: var(--color-vermilion);
   font-family: var(--font-typewriter);
   font-size: 0.62rem;
   line-height: 1.4;
 }
 .selection-actions__personas {
   position: absolute;
   top: calc(100% + 0.3rem);
   right: 0;
   width: min(18rem, calc(100vw - 1rem));
   max-height: min(22rem, 60vh);
   overflow-y: auto;
   border: 1px solid color-mix(in srgb, var(--color-ink-muted) 50%, transparent);
   background: color-mix(in srgb, var(--color-paper) 95%, transparent);
   box-shadow: 0 0.65rem 1.8rem rgba(32, 25, 16, 0.22);
   backdrop-filter: blur(14px);
 }
 .selection-actions__personas > p {
   padding: 0.45rem 0.6rem;
   border-bottom: 1px solid var(--color-paper-3);
   color: var(--color-ink-muted);
   font-family: var(--font-typewriter);
   font-size: 0.6rem;
   letter-spacing: 0.14em;
   text-transform: uppercase;
 }
 .selection-actions__personas > button {
   display: grid;
   width: 100%;
   grid-template-columns: 1.3rem minmax(0, 1fr);
   gap: 0.4rem;
   padding: 0.5rem 0.6rem;
   border-bottom: 1px solid
     color-mix(in srgb, var(--color-paper-3) 60%, transparent);
   text-align: left;
 }
 .selection-actions__personas > button:hover {
   background: var(--color-paper-soft);
 }
 .selection-actions__persona-mark {
   font-family: var(--font-display);
   font-size: 1rem;
 }
 .selection-actions__personas strong,
 .selection-actions__personas small {
   display: block;
 }
 .selection-actions__personas strong {
   color: var(--color-ink);
   font-family: var(--font-display);
   font-size: 0.78rem;
   font-weight: 600;
 }
 .selection-actions__personas small {
   margin-top: 0.1rem;
   color: var(--color-ink-muted);
   font-family: var(--font-typewriter);
   font-size: 0.58rem;
 }

 /* Writer and persona notes are one manuscript-edge conversation pattern.
    Authorship is carried by --comment-color, not by a second interface. */
 .manuscript-comment-card {
   position: fixed;
   z-index: var(--z-overlay);
   width: min(21.25rem, calc(100vw - 1.5rem));
   display: flex;
   flex-direction: column;
   overflow: hidden;
   border: 2px solid var(--comment-color);
   border-radius: 4px;
   background: var(--color-paper);
   box-shadow: 0 0.35rem 0.5rem rgba(32, 25, 16, 0.18);
 }
 .manuscript-comment-card__head {
   display: flex;
   min-height: 3.5rem;
   align-items: center;
   justify-content: space-between;
   gap: 0.75rem;
   padding: 0.75rem 1rem;
   border-bottom: 1px solid var(--color-paper-3);
   background: color-mix(
     in srgb,
     var(--comment-color) 7%,
     var(--color-paper-soft)
   );
 }
 .manuscript-comment-card__author {
   overflow: hidden;
   color: var(--color-ink);
   font-family: var(--font-display);
   font-size: 1rem;
   font-weight: 600;
   text-overflow: ellipsis;
   white-space: nowrap;
 }
 .manuscript-comment-card__label {
   margin-top: 0.125rem;
   font-family: var(--font-typewriter);
   font-size: 0.6875rem;
   letter-spacing: 0.12em;
   text-transform: uppercase;
 }
 .manuscript-comment-card__close {
   display: inline-flex;
   width: 2.75rem;
   height: 2.75rem;
   align-items: center;
   justify-content: center;
   color: var(--color-ink-muted);
   font-size: 1rem;
 }
 .manuscript-comment-card__close:hover {
   color: var(--color-ink);
 }
 .manuscript-comment-card__body {
   min-height: 0;
   overflow-y: auto;
   padding: 1rem;
 }
 .manuscript-comment-card__body > * + * {
   margin-top: 0.75rem;
 }
 .manuscript-comment-card__quote {
   padding: 0.75rem;
   border: 1px solid
     color-mix(in srgb, var(--comment-color) 34%, var(--color-paper-3));
   background: color-mix(
     in srgb,
     var(--comment-color) 6%,
     var(--color-paper-soft)
   );
   color: var(--color-ink-light);
   font-family: var(--font-serif);
   font-size: 0.8125rem;
   font-style: italic;
   line-height: 1.5;
 }
 .manuscript-comment-card__composer {
   padding-top: 0.75rem;
   border-top: 1px dashed var(--color-paper-3);
 }
 .manuscript-comment-card__textarea {
   width: 100%;
   min-height: 5.5rem;
   resize: vertical;
   padding: 0.625rem 0.75rem;
   border: 1px solid var(--color-paper-3);
   border-radius: 2px;
   background: var(--color-paper-soft);
   color: var(--color-ink);
   font-family: var(--font-serif);
   font-size: 0.8125rem;
   line-height: 1.5;
 }
 .manuscript-comment-card__textarea::placeholder {
   color: var(--color-ink-light);
 }
 .manuscript-comment-card__textarea:focus {
   border-color: var(--comment-color);
   outline: 2px solid color-mix(in srgb, var(--comment-color) 22%, transparent);
   outline-offset: 1px;
 }
 .manuscript-comment-card__actions {
   display: flex;
   align-items: center;
   justify-content: space-between;
   gap: 0.75rem;
   margin-top: 0.5rem;
 }
 .manuscript-comment-card__actions > span {
   color: var(--color-ink-muted);
   font-family: var(--font-typewriter);
   font-size: 0.625rem;
   letter-spacing: 0.1em;
 }

 @media (max-width: 520px) {
   .manuscript-comment-card {
     left: 0.5rem !important;
     right: 0.5rem;
     bottom: 0.5rem;
     top: auto !important;
     width: auto;
     max-height: 70vh;
   }
 }

 /* Comment: marginalia highlight */
 .twyne-editor .ProseMirror .comment-mark {
   background-color: color-mix(
     in srgb,
     var(--color-writer-note) 18%,
     transparent
   );
   border-bottom: 2px solid var(--color-writer-note);
   cursor: pointer;
 }

 /* Persona feedback line decoration */
 .persona-feedback-card {
   border-left-width: 3px;
 }

 /* Drag-over overlay */
 .drag-overlay {
   position: fixed;
   inset: 0;
   background: color-mix(in srgb, var(--color-vermilion) 7%, transparent);
   border: 2px dashed var(--color-vermilion);
   z-index: var(--z-overlay);
   display: flex;
   align-items: center;
   justify-content: center;
   pointer-events: none;
 }

 .drag-overlay span {
   background: var(--color-vermilion);
   color: var(--color-paper);
   padding: 0.75em 1.5em;
   border-radius: 2px;
   font-family: var(--font-typewriter);
   letter-spacing: 0.18em;
   text-transform: uppercase;
   font-size: 0.75rem;
 }

 /* Scrollbar for panels */
 .panel-scroll {
   overflow-y: auto;
   max-height: calc(100vh - 3rem);
 }

 .sidebar-transition {
   transition:
     width 0.2s ease,
     opacity 0.2s ease,
     transform 0.2s ease;
 }

 .focus-ring:focus-visible {
   outline: 2px solid var(--color-vermilion);
   outline-offset: 2px;
 }

 /* The rubric arrives as a proof sheet, then receives its grade as an ink
    impression. Both motions acknowledge a state change rather than decorating
    routine navigation. */
 .rubric-proof {
   position: relative;
   isolation: isolate;
   overflow: hidden;
   background-color: var(--color-paper-soft);
   background-image: url("/assets/rubric-proof-fibers.png");
   background-size: 24rem 24rem;
 }
 .rubric-proof::after {
   position: absolute;
   z-index: 0;
   inset: 0;
   box-shadow: inset 0 0 0 1px
     color-mix(in srgb, var(--color-ink-muted) 10%, transparent);
   content: "";
   opacity: 0.6;
   pointer-events: none;
 }
 .rubric-proof > * {
   position: relative;
   z-index: 1;
 }
 .rubric-proof--fresh {
   animation: rubric-proof-settle 380ms cubic-bezier(0.16, 1, 0.3, 1) both;
   transform-origin: top center;
 }

 .rubric-grade-stamp {
   --stamp-rotation: -4deg;
   position: relative;
   display: grid;
   flex: 0 0 auto;
   place-items: center;
   color: var(--color-ink);
   transform: rotate(var(--stamp-rotation));
   transform-origin: center;
   isolation: isolate;
 }
 .rubric-grade-stamp::before {
   position: absolute;
   inset: 0;
   background: currentColor;
   content: "";
   opacity: 0.82;
   -webkit-mask: var(--rubric-stamp-image) center / contain no-repeat;
   mask: var(--rubric-stamp-image) center / contain no-repeat;
   mix-blend-mode: multiply;
 }
 .rubric-grade-stamp--compact {
   width: 5rem;
   height: 3.45rem;
 }
 .rubric-grade-stamp--report {
   width: 8rem;
   height: 5.5rem;
 }
 .rubric-grade-stamp--a {
   --stamp-rotation: -5deg;
 }
 .rubric-grade-stamp--b {
   --stamp-rotation: 3deg;
 }
 .rubric-grade-stamp--c {
   --stamp-rotation: -2deg;
 }
 .rubric-grade-stamp--revise {
   --stamp-rotation: 4deg;
 }
 .rubric-grade-stamp--animated.rubric-grade-stamp--a {
   animation: rubric-stamp-a 340ms cubic-bezier(0.16, 1, 0.3, 1) both;
 }
 .rubric-grade-stamp--animated.rubric-grade-stamp--b {
   animation: rubric-stamp-b 340ms cubic-bezier(0.16, 1, 0.3, 1) both;
 }
 .rubric-grade-stamp--animated.rubric-grade-stamp--c {
   animation: rubric-stamp-c 350ms cubic-bezier(0.16, 1, 0.3, 1) both;
 }
 .rubric-grade-stamp--animated.rubric-grade-stamp--revise {
   animation: rubric-stamp-revise 360ms cubic-bezier(0.16, 1, 0.3, 1) both;
 }

 @keyframes rubric-proof-settle {
   from {
     filter: contrast(0.96) brightness(1.025);
     transform: translateY(-4px) scaleY(0.992);
   }
   to {
     filter: contrast(1) brightness(1);
     transform: translateY(0) scaleY(1);
   }
 }

 @keyframes rubric-stamp-a {
   from {
     filter: blur(1.2px);
     opacity: 0.3;
     transform: translateY(-12px) rotate(-9deg) scale(1.14);
   }
   to {
     filter: blur(0);
     opacity: 1;
     transform: translateY(0) rotate(-5deg) scale(1);
   }
 }

 @keyframes rubric-stamp-b {
   from {
     filter: blur(1px);
     opacity: 0.32;
     transform: translateY(-10px) rotate(7deg) scale(1.12);
   }
   to {
     filter: blur(0);
     opacity: 1;
     transform: translateY(0) rotate(3deg) scale(1);
   }
 }

 @keyframes rubric-stamp-c {
   from {
     filter: blur(0.9px);
     opacity: 0.34;
     transform: translateY(-9px) rotate(-5deg) scale(1.1);
   }
   to {
     filter: blur(0);
     opacity: 1;
     transform: translateY(0) rotate(-2deg) scale(1);
   }
 }

 @keyframes rubric-stamp-revise {
   from {
     filter: blur(0.75px);
     opacity: 0.36;
     transform: translateY(-7px) rotate(8deg) scale(1.08);
   }
   to {
     filter: blur(0);
     opacity: 1;
     transform: translateY(0) rotate(4deg) scale(1);
   }
 }

 /* Rubric score animation — fills from 0 to the inline width */
 @keyframes rubric-fill {
   from {
     width: 0;
   }
 }

 .rubric-bar {
   animation: rubric-fill 0.6s ease-out forwards;
 }

 /* A subtle hand-set wobble for the masthead — French Dispatch nod */
 @keyframes presswobble {
   0%,
   100% {
     transform: translate(0, 0) rotate(0deg);
   }
   25% {
     transform: translate(0.2px, -0.1px) rotate(-0.05deg);
   }
   75% {
     transform: translate(-0.15px, 0.1px) rotate(0.05deg);
   }
 }
 .press {
   animation: presswobble 4s ease-in-out infinite;
   display: inline-block;
 }

 /* Editorial button — a small set, hot-press feel */
 .btn-press {
   font-family: var(--font-typewriter);
   letter-spacing: 0.18em;
   text-transform: uppercase;
   font-size: 0.7rem;
   padding: 0.55rem 1rem;
   background: var(--color-ink);
   color: var(--color-paper);
   border: 1px solid var(--color-ink);
   border-radius: 2px;
   transition:
     transform 0.12s cubic-bezier(0.22, 1, 0.36, 1),
     background 0.18s ease,
     border-color 0.18s ease,
     box-shadow 0.18s ease;
   cursor: pointer;
 }
 .btn-press:hover {
   background: var(--color-vermilion-2);
   border-color: var(--color-vermilion-2);
   box-shadow: 0 4px 14px -8px
     color-mix(in srgb, var(--color-vermilion-2) 60%, transparent);
 }
 .btn-press:active {
   transform: translateY(1px) scale(0.98);
   box-shadow: none;
 }
 .btn-press:disabled {
   opacity: 0.4;
   cursor: not-allowed;
 }

 .btn-paper {
   font-family: var(--font-sans);
   font-size: 0.75rem;
   font-weight: 600;
   padding: 0.45rem 0.9rem;
   background: var(--color-paper-soft);
   color: var(--color-ink);
   border: 1px solid var(--color-paper-3);
   border-radius: 2px;
   transition:
     background 0.18s ease,
     border-color 0.18s ease,
     transform 0.12s cubic-bezier(0.22, 1, 0.36, 1),
     box-shadow 0.18s ease;
   cursor: pointer;
 }
 .btn-paper:hover {
   background: var(--color-paper-2);
   border-color: var(--color-ink-muted);
   box-shadow: 0 3px 10px -6px color-mix(in srgb, var(--shade) 25%, transparent);
 }
 .btn-paper:active {
   transform: translateY(1px);
   box-shadow: none;
 }

 .btn-press:focus-visible,
 .btn-paper:focus-visible,
 .landing-button:focus-visible {
   outline: 2px solid var(--color-vermilion);
   outline-offset: 2px;
 }

 /* Small icon-only control — consistent hit target + accessible focus */
 .icon-btn {
   display: inline-flex;
   align-items: center;
   justify-content: center;
   min-width: 1.75rem;
   min-height: 1.75rem;
   border-radius: 2px;
   color: var(--color-ink-muted);
   transition:
     color 0.15s ease,
     background 0.15s ease,
     transform 0.1s ease;
   cursor: pointer;
 }
 .icon-btn:hover {
   color: var(--color-ink);
   background: var(--color-paper-2);
 }
 .icon-btn:active {
   transform: scale(0.9);
 }
 .icon-btn:focus-visible {
   outline: 2px solid var(--color-vermilion);
   outline-offset: 1px;
 }

 /* Editor toolbar button — supports a pressed/active state */
 .tool-btn {
   padding: 0.25rem 0.5rem;
   font-size: 0.875rem;
   color: var(--color-ink-light);
   border-radius: 2px;
   transition:
     color 0.15s ease,
     background 0.15s ease,
     transform 0.1s ease;
   cursor: pointer;
 }
 .tool-btn:hover {
   color: var(--color-vermilion);
   background: var(--color-paper-soft);
 }
 .tool-btn:active {
   transform: scale(0.95);
 }
 .tool-btn[aria-pressed="true"] {
   color: var(--color-vermilion);
   background: var(--color-paper-2);
   box-shadow: inset 0 -2px 0 var(--color-vermilion);
 }
 .tool-btn:focus-visible {
   outline: 2px solid var(--color-vermilion);
   outline-offset: -2px;
 }

 /* ─────────────────────────────────────────────────────────────
  * Compositor ribbon
  *
  * Familiar document-editor tabs replace the old unbroken control strip.
  * Each tab exposes only the groups needed for its task, while history and
  * sync remain visible. Groups wrap as units so the manuscript never gains
  * a horizontal scrollbar.
  * ───────────────────────────────────────────────────────────── */
 .compositor-tabs {
   display: flex;
   min-width: 0;
   align-items: stretch;
   gap: 0.125rem;
   padding: 0 0.5rem;
   border-bottom: 1px solid var(--color-paper-3);
   background: var(--color-paper);
 }
 .compositor-title {
   display: inline-flex;
   align-items: center;
   padding: 0 0.75rem 0 0.25rem;
   color: var(--color-ink-muted);
   font-size: 0.625rem;
   letter-spacing: 0.14em;
   text-transform: uppercase;
 }
 .compositor-tab {
   min-height: 2.125rem;
   padding: 0.4rem 0.75rem 0.32rem;
   border-bottom: 2px solid transparent;
   color: var(--color-ink-light);
   font-family: var(--font-sans);
   font-size: 0.75rem;
   font-weight: 600;
 }
 .compositor-tab:hover {
   color: var(--color-ink);
   background: var(--color-paper-soft);
 }
 .compositor-tab[aria-selected="true"] {
   border-bottom-color: var(--color-vermilion);
   color: var(--color-vermilion);
   background: var(--color-paper-soft);
 }
 .compositor-tab:focus-visible {
   outline: 2px solid var(--color-vermilion);
   outline-offset: -2px;
 }
 .compositor-tab-spacer {
   flex: 1 1 auto;
 }
 .compositor-quick-actions {
   display: flex;
   align-items: center;
   gap: 0.125rem;
   padding-left: 0.375rem;
 }
 .compositor-ribbon {
   display: flex;
   min-width: 0;
   min-height: 3.75rem;
   flex-wrap: wrap;
   align-items: stretch;
   padding: 0.25rem 0.5rem 0;
 }
 .compositor-group {
   position: relative;
   display: none;
   flex: 0 0 auto;
   align-items: flex-start;
   gap: 0.0625rem;
   min-height: 3.5rem;
   padding: 0.25rem 0.5rem 1rem;
   border-right: 1px solid var(--color-paper-3);
 }
 .compositor-group::after {
   position: absolute;
   right: 0.5rem;
   bottom: 0.125rem;
   left: 0.5rem;
   overflow: hidden;
   color: var(--color-ink-muted);
   content: attr(data-group-label);
   font-family: var(--font-sans);
   font-size: 0.5625rem;
   line-height: 0.75rem;
   text-align: center;
   text-overflow: ellipsis;
   white-space: nowrap;
 }
 .twyne-toolbar[data-active-tab="home"] [data-compositor-tab="home"],
 .twyne-toolbar[data-active-tab="insert"] [data-compositor-tab="insert"],
 .twyne-toolbar[data-active-tab="review"] [data-compositor-tab="review"],
 .twyne-toolbar[data-active-tab="view"] [data-compositor-tab="view"] {
   display: flex;
 }
 .compositor-group:last-child {
   border-right: 0;
 }
 .compositor-group .tool-btn {
   display: inline-flex;
   min-height: 1.875rem;
   align-items: center;
   justify-content: center;
   gap: 0.25rem;
   white-space: nowrap;
 }
 .compositor-font-select,
 .compositor-size-select {
   height: 1.875rem;
   border: 1px solid var(--color-paper-3);
   border-radius: 2px;
   background: var(--color-paper);
   color: var(--color-ink);
   font-family: var(--font-sans);
   font-size: 0.7rem;
 }
 .compositor-font-select {
   width: 8.75rem;
   padding: 0 1.5rem 0 0.45rem;
 }
 .compositor-size-select {
   width: 3.75rem;
   padding: 0 1.25rem 0 0.4rem;
   font-variant-numeric: tabular-nums;
 }
 .compositor-font-select:hover,
 .compositor-size-select:hover {
   border-color: var(--color-ink-muted);
 }
 .compositor-font-select:focus-visible,
 .compositor-size-select:focus-visible {
   border-color: var(--color-vermilion);
   outline: 2px solid var(--color-vermilion);
   outline-offset: 1px;
 }
 .layout-panel-header {
   margin-bottom: 0.875rem;
 }
 .layout-panel-header h2 {
   color: var(--color-ink);
   font-family: var(--font-sans);
   font-size: 0.95rem;
   font-weight: 700;
 }
 .layout-panel-header p {
   margin-top: 0.125rem;
   color: var(--color-ink-muted);
   font-family: var(--font-serif);
   font-size: 0.72rem;
   line-height: 1.35;
 }
 .layout-section {
   min-width: 0;
   margin: 0;
   padding: 0.75rem 0;
   border: 0;
   border-top: 1px solid var(--color-paper-3);
 }
 .layout-section > legend {
   padding: 0 0.4rem 0 0;
   color: var(--color-ink-light);
   font-family: var(--font-sans);
   font-size: 0.65rem;
   font-weight: 700;
 }
 .layout-choice {
   min-height: 2rem;
   flex: 1 1 0;
   border: 1px solid var(--color-paper-3);
   border-radius: 2px;
   color: var(--color-ink-light);
   font-family: var(--font-sans);
   font-size: 0.7rem;
 }
 .layout-choice:hover {
   border-color: var(--color-ink-muted);
   color: var(--color-ink);
 }
 .layout-choice[aria-pressed="true"] {
   border-color: var(--color-vermilion);
   color: var(--color-vermilion);
   background: color-mix(in srgb, var(--color-vermilion) 8%, transparent);
   box-shadow: inset 0 -2px 0 var(--color-vermilion);
 }
 .layout-choice:focus-visible {
   outline: 2px solid var(--color-vermilion);
   outline-offset: 1px;
 }
 .compositor-check-row {
   display: flex;
   min-height: 2.25rem;
   align-items: center;
   justify-content: space-between;
   gap: 0.75rem;
   padding: 0.35rem 0.45rem;
   border-radius: 3px;
   color: var(--color-ink-light);
   cursor: pointer;
   font-family: var(--font-sans);
   font-size: 0.7rem;
 }
 .compositor-check-row:hover {
   background: var(--color-paper-soft);
 }
 .compositor-checkbox {
   width: 1.125rem;
   height: 1.125rem;
   flex: 0 0 auto;
   accent-color: var(--color-vermilion);
   cursor: pointer;
 }
 .compositor-checkbox:focus-visible {
   outline: 2px solid var(--color-vermilion);
   outline-offset: 2px;
 }
 .compositor-checkbox:disabled {
   cursor: not-allowed;
   opacity: 0.55;
 }

 @media (max-width: 639px) {
   .compositor-tabs {
     overflow-x: auto;
     overscroll-behavior-x: contain;
     scrollbar-width: thin;
   }
   .compositor-title {
     display: none;
   }
   .compositor-tab {
     min-height: 2.5rem;
     padding-inline: 0.65rem;
   }
   .compositor-tab-spacer {
     min-width: 0.25rem;
   }
   .compositor-quick-actions {
     position: sticky;
     right: 0;
     flex: none;
     padding-right: 0.25rem;
     background: var(--color-paper);
   }
   .compositor-ribbon {
     min-height: 0;
     gap: 0.125rem 0;
     padding: 0.25rem;
   }
   .compositor-group {
     min-height: 0;
     flex-wrap: wrap;
     padding: 0.125rem 0.25rem;
   }
   .compositor-group::after {
     display: none;
   }
   .compositor-group .tool-btn {
     min-width: 2.125rem;
     min-height: 2.125rem;
     padding: 0.4rem 0.5rem;
   }
   .compositor-layout-panel {
     position: fixed;
     inset: 5.25rem 0.75rem auto;
     width: auto;
     max-width: none;
     max-height: calc(100dvh - 6rem) !important;
   }
 }

 /* Editorial form controls — shared input vocabulary */
 .field-label {
   display: block;
   font-family: var(--font-typewriter);
   font-size: 0.625rem;
   letter-spacing: 0.32em;
   text-transform: uppercase;
   color: var(--color-ink-light);
   margin-bottom: 0.35rem;
 }
 .field-input {
   width: 100%;
   padding: 0.5rem 0.75rem;
   font-family: var(--font-serif);
   font-size: 0.875rem;
   color: var(--color-ink);
   background: var(--color-paper-soft);
   border: 1px solid var(--color-paper-3);
   border-radius: 2px;
 }
 .field-input::placeholder {
   color: var(--color-ink-muted);
   font-style: italic;
 }
 .field-input:focus {
   outline: none;
   border-color: var(--color-vermilion);
 }
 .field-input:focus-visible {
   outline: 1px solid var(--color-vermilion);
   outline-offset: 0;
 }

 /* Inline error note — letterpress slip, not a toast */
 .error-slip {
   padding: 0.6rem 0.8rem;
   border: 1px solid var(--color-vermilion);
   background: color-mix(in srgb, var(--color-vermilion) 5%, transparent);
   border-radius: 2px;
   color: var(--color-vermilion-2);
   font-family: var(--font-serif);
   font-size: 0.8125rem;
   line-height: 1.45;
 }

 /* Landing page surfaces */
 .landing-page {
   position: relative;
   overflow: clip;
   background:
     radial-gradient(
       circle at top left,
       color-mix(in srgb, var(--color-vermilion) 8%, transparent),
       transparent 26%
     ),
     radial-gradient(
       circle at 82% 18%,
       color-mix(in srgb, var(--color-periwinkle) 8%, transparent),
       transparent 18%
     ),
     linear-gradient(
       180deg,
       var(--color-paper-soft) 0%,
       var(--color-paper) 34%,
       var(--color-paper-2) 100%
     );
 }

 .landing-page::before {
   content: "";
   position: absolute;
   inset: 0;
   pointer-events: none;
   background-image:
     radial-gradient(circle at 15% 20%, var(--grain-1) 0, transparent 1px),
     radial-gradient(circle at 70% 40%, var(--grain-2) 0, transparent 1px),
     radial-gradient(circle at 85% 78%, var(--grain-3) 0, transparent 1px);
   background-size:
     9px 9px,
     11px 11px,
     13px 13px;
   opacity: 0.45;
 }

 .landing-shell {
   position: relative;
   z-index: 1;
   width: min(1440px, calc(100% - 1.5rem));
   margin: 0 auto;
 }

 .landing-frame {
   background: color-mix(in srgb, var(--color-paper-soft) 70%, transparent);
   border: 1px solid color-mix(in srgb, var(--color-vermilion-2) 8%, transparent);
   border-radius: 28px;
   box-shadow:
     0 1px 0 color-mix(in srgb, var(--emboss) 70%, transparent) inset,
     0 40px 80px -52px color-mix(in srgb, var(--shade) 28%, transparent);
   backdrop-filter: blur(10px);
 }

 .landing-kicker {
   font-family: var(--font-typewriter);
   letter-spacing: 0.28em;
   text-transform: uppercase;
   font-size: 0.7rem;
   color: var(--color-ink-muted);
 }

 .landing-title {
   font-family: var(--font-display);
   color: var(--color-ink);
   letter-spacing: -0.03em;
 }

 .landing-deck {
   font-family: var(--font-serif);
   color: var(--color-ink-light);
   line-height: 1.7;
 }

 .landing-button {
   display: inline-flex;
   align-items: center;
   justify-content: center;
   gap: 0.55rem;
   min-height: 2.8rem;
   padding: 0.7rem 1.4rem;
   border-radius: 999px;
   border: 1px solid transparent;
   font-family: var(--font-typewriter);
   font-size: 0.75rem;
   letter-spacing: 0.16em;
   text-transform: uppercase;
   transition:
     transform 0.15s ease,
     background 0.15s ease,
     border-color 0.15s ease;
 }

 .landing-button:hover {
   transform: translateY(-1px);
 }

 .landing-button.primary {
   background: var(--color-vermilion);
   color: var(--color-paper);
   border-color: var(--color-vermilion);
 }

 .landing-button.primary:hover {
   background: var(--color-vermilion-2);
   border-color: var(--color-vermilion-2);
 }

 .landing-button.secondary {
   background: transparent;
   color: var(--color-ink);
   border-color: color-mix(in srgb, var(--color-ink) 28%, transparent);
 }

 .landing-chip {
   display: inline-flex;
   align-items: center;
   gap: 0.4rem;
   padding: 0.4rem 0.85rem;
   border-radius: 999px;
   border: 1px solid color-mix(in srgb, var(--color-ink) 10%, transparent);
   background: color-mix(in srgb, var(--color-paper-soft) 55%, transparent);
   font-family: var(--font-typewriter);
   font-size: 0.64rem;
   letter-spacing: 0.2em;
   text-transform: uppercase;
   color: var(--color-ink-muted);
 }

 .landing-section-title {
   font-family: var(--font-display);
   color: var(--color-ink);
   letter-spacing: -0.02em;
 }

 .landing-feature-card {
   background: color-mix(in srgb, var(--color-paper-soft) 78%, transparent);
   border: 1px solid color-mix(in srgb, var(--color-ink) 6%, transparent);
   border-radius: 22px;
   box-shadow: 0 18px 38px -28px
     color-mix(in srgb, var(--shade) 22%, transparent);
   transition:
     transform 0.2s ease,
     box-shadow 0.2s ease;
 }
 .landing-feature-card:hover {
   transform: translateY(-2px);
   box-shadow: 0 26px 48px -30px
     color-mix(in srgb, var(--shade) 30%, transparent);
 }

 .landing-preview {
   background:
     linear-gradient(
       180deg,
       color-mix(in srgb, var(--emboss) 82%, transparent),
       color-mix(in srgb, var(--color-paper) 95%, transparent)
     ),
     repeating-linear-gradient(
       to bottom,
       transparent 0,
       transparent 29px,
       color-mix(in srgb, var(--color-periwinkle) 12%, transparent) 29px,
       color-mix(in srgb, var(--color-periwinkle) 12%, transparent) 30px
     );
   border: 1px solid color-mix(in srgb, var(--color-ink) 8%, transparent);
   border-radius: 20px;
   box-shadow:
     0 2px 0 color-mix(in srgb, var(--emboss) 60%, transparent) inset,
     0 44px 80px -48px color-mix(in srgb, var(--shade) 34%, transparent);
 }

 .landing-browser-bar {
   height: 2.2rem;
   border-bottom: 1px solid color-mix(in srgb, var(--color-ink) 8%, transparent);
   background: color-mix(in srgb, var(--color-paper-soft) 70%, transparent);
 }

 .landing-sidebar-card,
 .landing-board-card {
   background: color-mix(in srgb, var(--color-paper-soft) 70%, transparent);
   border: 1px solid color-mix(in srgb, var(--color-ink) 6%, transparent);
   border-radius: 14px;
 }

 .landing-quote {
   font-family: var(--font-display);
   font-style: italic;
   color: var(--color-ink-light);
 }

 /* ── Persona margin notes — inline marks in the manuscript ── */
 .twyne-persona-note {
   --note-color: var(--color-vermilion);
   cursor: text;
   background: color-mix(in srgb, var(--note-color) 11%, transparent);
   border-bottom: 2px dotted var(--note-color);
   transition: background 0.15s ease;
 }
 .twyne-persona-note:hover {
   background: color-mix(in srgb, var(--note-color) 22%, transparent);
 }
 .twyne-persona-note.is-flashing {
   animation: persona-note-flash 1.4s ease-out;
 }
 @keyframes persona-note-flash {
   0%,
   35% {
     background: color-mix(in srgb, var(--note-color) 38%, transparent);
   }
   100% {
     background: color-mix(in srgb, var(--note-color) 11%, transparent);
   }
 }

 .persona-note-card {
   position: fixed;
   z-index: var(--z-dropdown);
   width: min(20.5rem, calc(100vw - 1rem));
   padding: 0.85rem 1rem 1rem;
   background: var(--color-paper-soft);
   border: 1px solid
     color-mix(in srgb, var(--note-color) 45%, var(--color-paper-3));
   border-radius: 2px;
   box-shadow:
     0 1px 0 color-mix(in srgb, var(--emboss) 70%, transparent) inset,
     0 18px 36px -20px color-mix(in srgb, var(--shade) 50%, transparent);
   animation: persona-note-pop 0.18s cubic-bezier(0.22, 1, 0.36, 1);
 }
 @keyframes persona-note-pop {
   from {
     opacity: 0;
     transform: translateY(4px);
   }
   to {
     opacity: 1;
     transform: none;
   }
 }
 @media (prefers-reduced-motion: reduce) {
   .twyne-persona-note.is-flashing {
     animation: none;
     background: color-mix(in srgb, var(--note-color) 30%, transparent);
   }
   .persona-note-card {
     animation: none;
   }
 }

 /* ── Mark anchor chip ──
    A small dot rendered at the end of every contiguous run of three
    "comment-like" marks by the `MarkAnchorWidgets` ProseMirror plugin.
    Click it to open the matching popover without disturbing the caret
    in the marked text. The chip is the only hit target for these marks
    — hovering the marked text triggers the hover preview, not a chip
    click. */
 .twyne-mark-anchor {
   display: inline-block;
   vertical-align: middle;
   width: 0.5em;
   height: 0.5em;
   margin: 0 0.15em 0 0.25em;
   padding: 0;
   border: none;
   background: var(--note-color, var(--color-vermilion));
   color: inherit;
   border-radius: 999px;
   cursor: pointer;
   transform: scale(1);
   transition:
     transform 0.15s ease,
     opacity 0.15s ease;
   opacity: 0.55;
 }
 .twyne-mark-anchor:hover,
 .twyne-mark-anchor:focus-visible {
   transform: scale(1.6);
   opacity: 1;
   outline: none;
 }
 .twyne-mark-anchor:focus-visible {
   box-shadow:
     0 0 0 2px var(--color-paper),
     0 0 0 4px var(--note-color, var(--color-vermilion));
 }
 /* Hide the chip in zen mode — the marks themselves stay in place
    (the .zen-mode rule earlier already quiets them) but the chip is a
    UI affordance we suppress. */
 .twyne-editor.zen-mode .twyne-mark-anchor {
   display: none;
 }

 /* ── Suggestions — an editor's proposed rewrite, as a red-pencil mark ── */
 .twyne-suggestion {
   --suggestion-color: var(--color-vermilion);
   cursor: text;
   text-decoration: line-through;
   text-decoration-color: var(--suggestion-color);
   text-decoration-thickness: 2px;
   background: color-mix(in srgb, var(--suggestion-color) 9%, transparent);
   transition: background 0.15s ease;
 }
 .twyne-suggestion:hover {
   background: color-mix(in srgb, var(--suggestion-color) 20%, transparent);
 }
 .twyne-suggestion.is-flashing {
   animation: persona-note-flash 1.4s ease-out;
 }

 .suggestion-card {
   position: fixed;
   z-index: var(--z-dropdown);
   width: min(21rem, calc(100vw - 1rem));
   padding: 0.85rem 1rem 1rem;
   background: var(--color-paper-soft);
   border: 1px solid
     color-mix(in srgb, var(--suggestion-color) 45%, var(--color-paper-3));
   border-radius: 2px;
   box-shadow:
     0 1px 0 color-mix(in srgb, var(--emboss) 70%, transparent) inset,
     0 18px 36px -20px color-mix(in srgb, var(--shade) 50%, transparent);
   animation: persona-note-pop 0.18s cubic-bezier(0.22, 1, 0.36, 1);
 }

 /* The approval stamp — a vermilion rubber stamp thunking onto the page. */
 .approval-stamp-overlay {
   position: fixed;
   inset: 0;
   display: flex;
   align-items: center;
   justify-content: center;
   pointer-events: none;
   z-index: var(--z-modal, 1000);
 }
 .approval-stamp-overlay img {
   animation: stamp-thunk 1.2s cubic-bezier(0.18, 1.4, 0.4, 1) forwards;
   transform-origin: center;
   filter: drop-shadow(
     0 8px 18px color-mix(in srgb, var(--color-vermilion-2) 35%, transparent)
   );
 }
 @keyframes stamp-thunk {
   0% {
     opacity: 0;
     transform: scale(1.8) rotate(-14deg);
   }
   18% {
     opacity: 1;
     transform: scale(0.92) rotate(-7deg);
   }
   32% {
     transform: scale(1.04) rotate(-9deg);
   }
   46% {
     transform: scale(1) rotate(-8deg);
   }
   80% {
     opacity: 1;
     transform: scale(1) rotate(-8deg);
   }
   100% {
     opacity: 0;
     transform: scale(1.02) rotate(-8deg);
   }
 }
 @media (prefers-reduced-motion: reduce) {
   .twyne-suggestion.is-flashing {
     animation: none;
     background: color-mix(in srgb, var(--suggestion-color) 28%, transparent);
   }
   .suggestion-card {
     animation: none;
   }
   .approval-stamp-overlay img {
     animation: stamp-fade 1s ease-out forwards;
   }
   @keyframes stamp-fade {
     0% {
       opacity: 0;
     }
     20%,
     80% {
       opacity: 1;
       transform: rotate(-8deg);
     }
     100% {
       opacity: 0;
     }
   }
 }

 /* Landing masthead logotype, echoes the in-app masthead */
 .landing-masthead {
   font-family: var(--font-display);
   font-weight: 700;
   font-size: 2rem;
   line-height: 1;
   letter-spacing: 0.06em;
   color: var(--color-ink);
 }

 .landing-masthead-grand {
   font-family: var(--font-display);
   font-weight: 700;
   font-size: clamp(3.25rem, 10vw, 5.75rem);
   line-height: 1;
   letter-spacing: 0.05em;
   color: var(--color-ink);
 }

 /* Landing masthead nav */
 .landing-nav-link {
   font-family: var(--font-typewriter);
   font-size: 0.78rem;
   letter-spacing: 0.14em;
   text-transform: uppercase;
 }

 /* Shared masthead hover: a vermilion rule drawn in from the left. The
    sign-in link sits in the same masthead but keeps its own smaller type,
    so the sweep lives here rather than inside .landing-nav-link. */
 .landing-nav-link,
 .landing-signin-link {
   position: relative;
   color: var(--color-ink-light);
   transition:
     color 0.15s ease,
     letter-spacing 0.2s ease;
 }
 .landing-nav-link::after,
 .landing-signin-link::after {
   content: "";
   position: absolute;
   left: 0;
   right: 0;
   bottom: -2px;
   height: 1px;
   background: var(--color-vermilion);
   transform: scaleX(0);
   transform-origin: left;
   transition: transform 0.2s cubic-bezier(0.22, 1, 0.36, 1);
 }
 .landing-nav-link:hover,
 .landing-signin-link:hover {
   color: var(--color-vermilion);
 }
 .landing-nav-link:hover::after,
 .landing-signin-link:hover::after {
   transform: scaleX(1);
 }
 .landing-nav-link:focus-visible,
 .landing-signin-link:focus-visible {
   outline: 2px solid var(--color-vermilion);
   outline-offset: 3px;
 }

