.landing-nav-link:hover::after,
.landing-signin-link:hover::after {
  transform: scaleX(1);
}
.landing-nav-link:focus-visible,
.landing-signin-link:focus-visible {
  outline: 2px solid var(--color-vermilion);
  outline-offset: 3px;
}

/* Annotation slips pinned over the workspace preview */
.landing-annotation {
  position: absolute;
  z-index: 2;
  pointer-events: none;
  max-width: 15.5rem;
  padding: 0.6rem 0.8rem;
  background: var(--color-paper-soft);
  border: 1px solid color-mix(in srgb, var(--color-ink) 20%, transparent);
  border-radius: 2px;
  box-shadow: 0 14px 28px -18px
    color-mix(in srgb, var(--shade) 50%, transparent);
}
.landing-annotation .tag {
  font-family: var(--font-typewriter);
  font-size: 0.72rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}
.landing-annotation .note {
  margin-top: 0.2rem;
  font-family: var(--font-serif);
  font-size: 0.875rem;
  line-height: 1.45;
  color: var(--color-ink-light);
}

/* Step numerals in the how-it-works ledger */
.landing-step-num {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 1.5rem;
  line-height: 1;
  color: var(--color-vermilion);
}

/* Hero entrance: starts visible-safe via `both` keyframe fill */
@keyframes landing-rise {
  from {
    opacity: 0;
    transform: translateY(16px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
.landing-rise,
.landing-rise-2,
.landing-rise-3 {
  animation: landing-rise 0.7s cubic-bezier(0.22, 1, 0.36, 1) both;
}
.landing-rise-2 {
  animation-delay: 0.12s;
}
.landing-rise-3 {
  animation-delay: 0.24s;
}
@media (prefers-reduced-motion: reduce) {
  .landing-rise,
  .landing-rise-2,
  .landing-rise-3 {
    animation: none;
  }
}

