/**
 * One-off: ask Jev (TypeSafe System One, direct local-dev path) to judge the
 * room-tour work: interface design, visual styling, and Qwik code quality.
 * Reads the touched files as judgement state. Prints the verdict as JSON.
 */
import { readFileSync } from "node:fs";
import { judgementQuestions } from "/home/diogenes/Projects/twyne/convex/lib/judgementContract.ts";

const DIRECT_ENDPOINT = "https://api.typesafe.ai/v1/systemone";
const key = process.env.TYPESAFE_API_KEY?.trim();
if (!key) throw new Error("TYPESAFE_API_KEY missing");

const tour = readFileSync(
  "/home/diogenes/Projects/twyne/src/components/landing/workspace-tour.tsx",
  "utf-8",
);
const preview = readFileSync(
  "/home/diogenes/Projects/twyne/src/components/landing/workspace-preview.tsx",
  "utf-8",
);
const css = readFileSync(
  "/home/diogenes/Projects/twyne/src/global.css",
  "utf-8",
);
const tourCss = css
  .split("\n")
  .filter((_, i) => {
    const line = i + 1;
    return line >= 2615 && line <= 2780;
  })
  .join("\n");

const context = [
  "Context: Twyne is a Qwik (Qwik.dev core v2) writing app with an editorial",
  "broadsheet design language — paper backgrounds, ink text, typewriter Hund",
  "labels (dept-label), display serif headlines, vermilion/cobalt/mustard/",
  "periwinkle/sage accents via var(--color-*). Components use component$,",
  "useSignal, useVisibleTask$; props flow down, callbacks ($-wrapped) flow up.",
  "The WorkspaceTour overlays pulsing hotspots on a WorkspacePreview mock",
  "(drawer + manuscript + 5-tab editorial board) and shows a floating reader",
  "slip next to the active hotspot. It auto-advances every 5s, pauses on",
  "hover/focus, disables the loop under prefers-reduced-motion, and syncs",
  "both ways with the preview (callbacks drive the card; hotspots drive the",
  "preview). On narrow screens the slip docks as a bottom sheet.",
].join(" ");

const state = { context, "workspace-tour.tsx": tour, "workspace-preview.tsx": preview, "tour.css": tourCss };
const chars = Object.values(state).reduce((n, s) => n + s.length, 0);
console.error(`state chars: ${chars}`);

const questions = judgementQuestions({
  interface_design: {
    type: "score",
    instructions:
      "Judge the INTERFACE DESIGN of the room tour from the state files. " +
      "Consider: can a first-time visitor understand each of the 8 parts of " +
      "the workspace without scrolling; hotspot discoverability (desktop-only " +
      "hotspots vs always-available dots/arrows); whether the floating slip " +
      "placement (above/below per stop, bottom sheet on mobile) keeps the " +
      "described element visible; auto-advance timing and pause behavior; " +
      "whether two-way sync (preview interactions move the card) helps or " +
      "confuses. Score 0=poor, 1=weak, 2=adequate, 3=strong, 4=exceptional. " +
      "Include a 'rationale' string (2-4 sentences) and a 'suggestions' array " +
      "of short concrete strings in your answer.",
    criteria: ["poor", "weak", "adequate", "strong", "exceptional"],
  },
  visual_styling: {
    type: "score",
    instructions:
      "Judge the VISUAL STYLING of the tour (tour.css plus the class usage in " +
      "workspace-tour.tsx). Consider: consistency with the editorial broadsheet " +
      "language (paper-soft slips, typewriter tags, serif notes, accent left " +
      "border); hotspot aesthetics (pulse ring, active fill); restraint of the " +
      "overlay (size, shadow, z-order over the preview); mobile bottom-sheet " +
      "treatment. Score 0=poor, 1=weak, 2=adequate, 3=strong, 4=exceptional. " +
      "Include a 'rationale' string (2-4 sentences) and a 'suggestions' array " +
      "of short concrete strings in your answer.",
    criteria: ["poor", "weak", "adequate", "strong", "exceptional"],
  },
  code_quality: {
    type: "score",
    instructions:
      "Judge the QWIK CODE QUALITY of workspace-tour.tsx and the controlled " +
      "props added to workspace-preview.tsx. Consider: correct signal usage " +
      "(no stale closures in the interval — goTo reads stopIndex.value at " +
      "fire time); SSR safety of useVisibleTask$ with matchMedia/setInterval " +
      "and its cleanup; the controlled/uncontrolled fallback pattern in the " +
      "preview; accessibility (tablist/tab roles, aria-selected/pressed, " +
      "labels, focus-visible styles, reduced-motion handling); dead code or " +
      "over-complex derivations. Score 0=poor, 1=weak, 2=adequate, 3=strong, " +
      "4=exceptional. Include a 'rationale' string (2-4 sentences) and a " +
      "'suggestions' array of short concrete strings in your answer.",
    criteria: ["poor", "weak", "adequate", "strong", "exceptional"],
  },
  biggest_risk: {
    type: "choice",
    instructions:
      "Which is the most significant REMAINING weakness of this tour? " +
      "Options: 'slip-covers-content' (the overlay hides what it describes); " +
      "'hotspot-discoverability' (visitors never notice the hotspots/dots); " +
      "'auto-advance-timing' (5s loop fights reading or interaction); " +
      "'tour-copy-clarity' (the stop notes fail to explain the interface); " +
      "'no-significant-risk' (ship it). " +
      "Include a 'rationale' string (1-2 sentences) in your answer.",
    criteria: [
      "slip-covers-content",
      "hotspot-discoverability",
      "auto-advance-timing",
      "tour-copy-clarity",
      "no-significant-risk",
    ],
  },
});

const res = await fetch(DIRECT_ENDPOINT, {
  method: "POST",
  signal: AbortSignal.timeout(90_000),
  headers: { "Content-Type": "application/json", Authorization: `Bearer ${key}` },
  body: JSON.stringify({ model: "jev-latest", state, questions }),
});
if (!res.ok) {
  console.error(`http ${res.status}`);
  process.exit(1);
}
const body = await res.json();
console.log(JSON.stringify(body, null, 2));

