/**
 * Quality sweep with Jev: (1) audit the generative judge prompts in
 * prompts/ for structural problems; (2) meta-audit our own System One
 * question design in src/utils/note-gate.ts. Two requests, one per state.
 */
import { readFileSync } from "node:fs";
import { judgementQuestions } from "/home/diogenes/Projects/twyne/convex/lib/judgementContract.ts";

const DIRECT_ENDPOINT = "https://api.typesafe.ai/v1/systemone";
const key = process.env.TYPESAFE_API_KEY?.trim();
if (!key) throw new Error("TYPESAFE_API_KEY missing");

const P = "/home/diogenes/Projects/twyne/prompts/";
const read = (f: string) => readFileSync(P + f, "utf-8");

async function ask(state: Record<string, string>, questions: unknown, tag: string) {
  const res = await fetch(DIRECT_ENDPOINT, {
    method: "POST",
    signal: AbortSignal.timeout(90_000),
    headers: { "Content-Type": "application/json", Authorization: `Bearer ${key}` },
    body: JSON.stringify({ model: "jev-latest", state, questions }),
  });
  if (!res.ok) throw new Error(`${tag}: http ${res.status}`);
  return { tag, ...(await res.json()) };
}

// ── Request 1: audit the generative judge prompts ──
const promptState = {
  context: [
    "These are LLM prompts shipped by a writing app. Each *-system.md sets the",
    "role; each *-user.md is rendered with {placeholders} substituted at call",
    "time: {goal}, {audience}, {draftText} (the writer's full draft),",
    "{staticNote} (heuristic signals), {format}, {successSignal},",
    "{particulars}. The model must reply with JSON only. Judge the prompts",
    "themselves as engineering artifacts, not any draft.",
  ].join(" "),
  "target-fit": read("target-fit-judge-system.md") + "\n---\n" + read("target-fit-judge-user.md"),
  integrity: read("integrity-judge-system.md") + "\n---\n" + read("integrity-judge-user.md"),
  evidence: read("evidence-judge-system.md") + "\n---\n" + read("evidence-judge-user.md"),
  sufficiency: read("sufficiency-judge-system.md"),
  "dossier-check": read("dossier-check-system.md"),
};

const promptQuestions = judgementQuestions({
  injection_surface: {
    type: "noul",
    instructions:
      "Does any prompt in `prompts` interpolate untrusted content — the writer's draft text, goals, or heuristic notes — without delimiters, hierarchy labels, or an explicit instruction not to follow instructions found inside the interpolated content, so that draft text could steer the judge?",
  },
  self_contradiction: {
    type: "noul",
    instructions:
      "Does any prompt demand two incompatible things — for example telling the judge to ignore craft entirely while judging audience fit that depends on clarity, or anchoring a 1-to-10 scale with only four described levels so most scores have no defined meaning?",
  },
  output_fragility: {
    type: "noul",
    instructions:
      "Does any prompt's demanded JSON-only output risk parse failure or ambiguous grading — for example a free-text rationale field with no escaping rule for quotes and newlines, or score anchors that leave most of the 1-to-10 range undescribed?",
  },
  weakest_prompt: {
    type: "choice",
    instructions:
      "Which prompt is the weakest engineering artifact overall? target-fit judges whether the draft serves its commission; integrity judges honesty of the prose; evidence judges whether citations support claims; sufficiency judges whether the draft develops enough material; dossier-check lists dossier fields the draft outgrew.",
    criteria: [
      "target-fit",
      "integrity",
      "evidence",
      "sufficiency",
      "dossier-check",
      "none-significant",
    ],
  },
});

// ── Request 2: meta-audit our own System One question design ──
const gateSrc = readFileSync(
  "/home/diogenes/Projects/twyne/src/utils/note-gate.ts",
  "utf-8",
).split("\n").slice(0, 200).join("\n");

const gateState = {
  context: [
    "This is TypeScript that builds typed Jev questions for gating persona",
    "notes: Score questions carry ordered worst-first level descriptions;",
    "Noul questions carry yes-or-no instructions. Levels are matched against",
    "a note, its passage, the draft, the brief, and the editor persona.",
  ].join(" "),
  "note-gate.ts (header, levels, question builders)": gateSrc,
};

const gateQuestions = judgementQuestions({
  levels_distinct: {
    type: "score",
    instructions:
      "Do the HELPFUL, ACTIONABLE, SERVES_GOAL, and ADHERENCE level sets each describe distinctly matchable situations, so a note lands on exactly one level per set?",
    criteria: [
      "Levels overlap heavily; a note could match several equally",
      "Mostly distinct with blur between neighbors",
      "Each level names a distinct, matchable situation",
    ],
  },
  noul_discipline: {
    type: "noul",
    instructions:
      "Is every Noul (violatesConstraints, movesSuccessSignal, breaksAvoidance, violatesWriterFacts, violatesFeedbackPreferences) a genuine yes-or-no fact about the note rather than a disguised quality magnitude?",
  },
  missing_dimension: {
    type: "choice",
    instructions:
      "Which useful gating dimension is missing from this design? quote-accuracy means checking the note quotes the draft faithfully; severity-routing means deciding block versus suggest; staleness means checking the note still applies to the current draft.",
    criteria: [
      "quote-accuracy",
      "severity-routing",
      "staleness",
      "none-significant",
    ],
  },
});

const [r1, r2] = await Promise.all([
  ask(promptState, promptQuestions, "prompt-audit"),
  ask(gateState, gateQuestions, "gate-audit"),
]);
console.log(JSON.stringify([r1, r2], null, 2));

