for (const r of [r1,r2]) { console.log('=== '+r.tag+' ('+r.model+') ==='); for (const [k,a] of Object.entries(r.answers)) console.log(k,'=>', a.score ?? a.choice ?? a.noul, '| conf:', a.confidence ?? 'n/a', '| probs:', JSON.stringify(a.probabilities ?? {})); }
"

