    overall < thresholds.minOverall ||
    present.some((d) => d.score < thresholds.minDimension);
  const voiceFailed =
    (adherence !== null && adherence.score < thresholds.minAdherence) ||
    (breaksAvoidance !== null &&
      breaksAvoidance > thresholds.maxAvoidanceRisk);
  const factsFailed =
