                            {source.ok ? "✓" : "✕"} {source.status}
                          </span>
                        </li>
                      ))}
                    </ul>
                  </div>
                )}

                {currentTab === "history" && (
                  <div>
                    <p class="dept-label">Version history · 3 revisions</p>
                    <ol class="mt-3 space-y-2">
                      {demoVersions.map((version) => (
                        <li
