                     ]}
                   >
                     <figure
                       class="landing-plate__figure"
                       data-reveal
                       style={`--tilt: ${step.tilt}; --drift-x: ${step.driftX}; --drift-y: ${step.driftY}`}
                     >
-                      <div
-                        class={[
-                          "landing-plate__frame",
-                          portrait ? "landing-plate__frame--portrait" : "",
-                        ]}
-                      >
+                      <div class="landing-plate__frame">
                         <Preview />
                       </div>
