   font-family: var(--font-display);
   font-weight: 700;
   font-size: 1.5rem;
   line-height: 1;
   color: var(--color-vermilion);
 }

 /* Hero entrance: starts visible-safe via `both` keyframe fill */
 @keyframes landing-rise {
   from {
     opacity: 0;
     transform: translateY(16px);
   }
   to {
     opacity: 1;
     transform: none;
   }
