+   leave a dead band under the shorter ones. */
 .landing-plate__frame {
   overflow: hidden;
   border-radius: 2px;
-  aspect-ratio: 3 / 2;
   background: var(--color-paper-3);
 }
-.landing-plate__frame--portrait {
-  aspect-ratio: 4 / 5;
-}
 .landing-plate__frame img {
   width: 100%;
   height: 100%;
   object-fit: cover;
   display: block;
 }

 /* Photographic bleed behind the closing CTA. Washed right back and
    feathered at the edges so it reads as paper texture, not a picture. */
 .landing-closing-photo {
   position: absolute;
   inset: 0;
   width: 100%;
   height: 100%;
   object-fit: cover;
   opacity: 0.18;
   pointer-events: none;
   mask-image: radial-gradient(ellipse at center, #000 30%, transparent 78%);
 }
 [data-theme="nightpress"] .landing-closing-photo {
   opacity: 0.26;
 }

 .landing-plate__label {
   display: inline-block;
   font-family: var(--font-typewriter);
   font-size: 0.68rem;
   letter-spacing: 0.24em;
   text-transform: uppercase;
   color: var(--color-vermilion);
   transform: rotate(-1.1deg);
   transform-origin: left center;
 }

 /* ── Scroll reveal ── */
 [data-reveal-ready] [data-reveal] {
   opacity: 0;
   transform: translateY(16px);
   transition:
     opacity 0.7s cubic-bezier(0.22, 1, 0.36, 1),
     transform 0.7s cubic-bezier(0.22, 1, 0.36, 1);
   transition-delay: var(--reveal-delay, 0ms);
 }
