     opacity: 1;
     transform: translate(var(--drift-x), var(--drift-y)) rotate(var(--tilt));
   }
   /* Never hide content when motion is unwelcome. */
   [data-reveal-ready] [data-reveal] {
     opacity: 1;
     transform: none;
     transition: none;
   }
 }

