    opacity: 0;
    transform: translateY(-0.34em);
  }
}

/* The struck words stay legible under the rule — a correction shows its
   working, it doesn't hide it — but drop back so the replacement leads. */
.landing-title .landing-rotator__struck {
  position: relative;
  color: var(--mark-dim, var(--color-ink-muted));
}
.landing-title .landing-rotator__struck::after {
  content: "";
  position: absolute;
  left: -0.03em;
  right: -0.03em;
  top: 0.52em;
  height: 0.07em;
  border-radius: 0.04em;
  background: var(--mark, var(--color-vermilion));
  transform: scaleX(0);
  transform-origin: left;
  animation: landing-strike 0.42s cubic-bezier(0.22, 1, 0.36, 1) forwards;
}
@keyframes landing-strike {
  to {
    transform: scaleX(1);
  }
}

.landing-title .landing-rotator__caret {
  display: inline-block;
  width: 0.07em;
  height: 0.78em;
  margin-left: 0.07em;
  vertical-align: -0.02em;
  background: var(--mark, var(--color-vermilion));
  animation: type-blink 1.05s steps(1, end) infinite;
}

/* The deck changes with the headline; it is keyed, so this replays.
 *
 * It also has to reserve its own height. Two things move it otherwise: the
 * decks differ in line count once they wrap (four lines vs three on a phone),
 * and before the webfont lands the fallback sets shorter. Either one drags
 * the CTAs underneath it — measured at 0.04 CLS before this reserve. */
.landing-rotator-deck {
  min-height: 6.9em;
  animation: landing-deck-in 0.5s cubic-bezier(0.22, 1, 0.36, 1) both;
}
@media (min-width: 640px) {
  /* Past the wrap point every deck settles to two lines. */
  .landing-rotator-deck {
    min-height: 3.5em;
  }
}
@keyframes landing-deck-in {
  from {
    opacity: 0;
    transform: translateY(6px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

/* ── Headings that type themselves in when scrolled to ──
   Each character is its own step, delayed by its position, so the reveal
   reads as keystrokes rather than a fade. Characters are visible by default
   and only hidden once the observer is installed, so a page without JS
   simply reads. */
@keyframes landing-type-in {
  to {
    opacity: 1;
  }
}
.landing-typed__word {
  display: inline-block;
  white-space: pre;
}
/* The keystrokes replace the container fade — one reveal, not two. */
[data-reveal-ready] [data-reveal].landing-typed-reveal {
  opacity: 1;
  transform: none;
}
[data-reveal-ready] .landing-typed-reveal .landing-typed__char {
  opacity: 0;
}
[data-reveal-ready] .landing-typed-reveal.is-revealed .landing-typed__char,
[data-reveal-ready]
  [data-reveal].is-revealed
  .landing-typed-reveal
  .landing-typed__char {
  animation: landing-type-in 1ms steps(1, end) forwards;
  animation-delay: calc(var(--i) * 34ms);
}

@media (prefers-reduced-motion: reduce) {
  .landing-rotator.is-leaving,
  .landing-rotator-deck {
    animation: none;
  }
  .landing-title .landing-rotator__struck::after {
    animation: none;
    transform: scaleX(1);
  }
  /* A caret that cannot blink is just a stray mark. */
  .landing-title .landing-rotator__caret {
    display: none;
  }
  [data-reveal-ready] .landing-typed-reveal .landing-typed__char {
    opacity: 1;
    animation: none;
  }
}

/* ── One spread ── */
.landing-plate {
  display: grid;
  gap: 1.75rem;
  align-items: center;
}
@media (min-width: 768px) {
  .landing-plate {
    grid-template-columns: 1fr 1fr;
    gap: 3.5rem;
  }
  /* A portrait plate at half-width stands taller than its facing copy and
     opens a dead gap, so give it a narrower column than the landscape ones. */
  .landing-plate--portrait {
