        grid-template-columns: repeat(3, 1fr);
      }
    }
    .dl-card {
      position: relative;
      display: flex;
      flex-direction: column;
      gap: 0.5rem;
      padding: 1.1rem 1.1rem 1.2rem;
      background: var(--color-paper-soft);
      border: 1px solid var(--color-paper-3);
      border-radius: 3px;
      box-shadow:
        0 1px 0 rgba(255, 255, 255, 0.6) inset,
        0 10px 26px -22px rgba(31, 27, 22, 0.45);
      transition:
        transform 0.15s ease,
        box-shadow 0.15s ease,
        border-color 0.15s ease;
    }
    .dl-card:hover {
      transform: translateY(-2px);
      border-color: var(--color-vermilion);
      box-shadow:
        0 1px 0 rgba(255, 255, 255, 0.6) inset,
        0 18px 34px -22px rgba(31, 27, 22, 0.5);
    }
    .dl-card-recommended {
      border-color: var(--color-vermilion);
      border-width: 2px;
      padding: calc(1.1rem - 1px) calc(1.1rem - 1px) calc(1.2rem - 1px);
    }
    .dl-stamp {
      position: absolute;
      top: -0.6rem;
      right: -0.6rem;
      width: 3.4rem;
      height: 3.4rem;
      opacity: 0;
      pointer-events: none;
      animation: dl-stamp-down 0.4s ease-out 0.05s forwards;
    }
    .dl-stamp-soon {
      opacity: 0.85;
      animation: none;
    }
    @keyframes dl-stamp-down {
      0% {
        opacity: 0;
        transform: scale(1.6) rotate(4deg);
      }
      70% {
        opacity: 1;
        transform: scale(0.92) rotate(4deg);
      }
      100% {
        opacity: 0.9;
        transform: scale(1) rotate(4deg);
      }
    }
    .dl-glyph {
      font-size: 1.6rem;
      line-height: 1;
    }
    .dl-name {
      font-family: var(--font-display);
      font-weight: 700;
      font-size: 1.15rem;
      color: var(--color-ink);
    }
    .dl-format {
      font-family: var(--font-typewriter);
      font-size: 0.62rem;
      text-transform: uppercase;
      letter-spacing: 0.14em;
      color: var(--color-ink-muted);
    }
