input.content:
/**
 * Minimal CHANGELOG.md reader for the downloads page's release-notes
 * section. The changelog is the release notes — parsed at build time from
 * the repo's own file so visitors read what changed without leaving the
 * site, and the notes can never drift from the published history.
 *
 * Only the structure below is understood; anything else passes through as
 * plain bullets. Keep entries in this shape:
 *
 *   ## 0.18.0
 *   <sub>2026-08-27</sub>
 *
 *   - First highlight…
 */

export interface ChangelogEntry {
  version: string;
  date: string | null;
  highlights: string[];
}

/** How many releases the downloads page shows. */
export const RELEASE_NOTES_COUNT = 3;
/** Bullets per release before the entry is trimmed. */
export const RELEASE_NOTES_BULLETS = 6;

export function parseChangelog(markdown: string): ChangelogEntry[] {
  const entries: ChangelogEntry[] = [];
  const sections = markdown.split(/^## /m);
  for (const section of sections.slice(1)) {
    const lines = section.split("\n");
    const version = lines[0]?.trim().replace(/^v/, "") ?? "";
    if (!version) continue;
    const date =
      section.match(/<sub>(\d{4}-\d{2}-\d{2})<\/sub>/)?.[1] ?? null;
    const highlights = lines
      .filter((line) => line.startsWith("- "))
      .map((line) =>
        line
          .replace(/^-+\s+/, "")
          .replace(/\*\*/g, "")
          .trim(),
      )
      .filter(Boolean)
      .slice(0, RELEASE_NOTES_BULLETS);
    entries.push({ version, date, highlights });
  }
  return entries;
}

import { describe, expect, test } from "bun:test";
import { parseChangelog } from "./changelog";

describe("parseChangelog", () => {
  test("reads versions, dates, and top-level bullets", () => {
    const entries = parseChangelog(
      [
        "# Changelog",
        "",
        "## 0.18.0",
        "<sub>2026-08-27</sub>",
        "",
        "- **My Desk turns usage into a writing history.** A new workspace.",
        "- Second highlight.",
        "  - nested detail, not a highlight",
        "",
        "## 0.17.0",
        "",
        "- Older highlight.",
        "",
      ].join("\n"),
    );
    expect(entries).toHaveLength(2);
    expect(entries[0]).toMatchObject({
      version: "0.18.0",
      date: "2026-08-27",
    });
    expect(entries[0].highlights).toEqual([
      "My Desk turns usage into a writing history. A new workspace.",
      "Second highlight.",
    ]);
    expect(entries[1]).toMatchObject({ version: "0.17.0", date: null });
  });

  test("trims long entries to a readable handful", () => {
    const bullets = Array.from({ length: 20 }, (_, i) => `- point ${i}`).join(
      "\n",
    );
    const [entry] = parseChangelog(`## 1.0.0\n<sub>2026-01-01</sub>\n\n${bullets}\n`);
    expect(entry.highlights).toHaveLength(6);
  });

