     .dl-benefits {
       list-style: none;
       margin: 0.5rem 0 1rem;
       padding: 0;
       display: grid;
       gap: 0.5rem;
     }
     .dl-benefits li {
       font-family: var(--font-serif);
       font-size: 0.9rem;
       line-height: 1.55;
       color: var(--color-ink-light);
       padding-left: 1.4rem;
       position: relative;
     }
     .dl-benefits li::before {
       content: "✦";
       position: absolute;
       left: 0;
       top: 0.05rem;
       color: var(--color-vermilion);
       font-size: 0.75rem;
