     .dl-web {
       display: flex;
       flex-wrap: wrap;
       align-items: center;
       gap: 0.9rem;
       padding: 1.1rem 1.2rem;
       background: var(--color-paper);
       border: 1px dashed var(--color-paper-3);
       border-radius: 3px;
     }
     .dl-web-body {
       flex: 1 1 16rem;
     }
     .dl-web-body p {
       margin: 0.3rem 0 0;
       font-family: var(--font-serif);
       font-size: 0.88rem;
       line-height: 1.55;
       color: var(--color-ink-light);
     }
     .dl-checks {
       list-style: none;
       margin: 0.4rem 0 0;
       padding: 0;
       display: grid;
       gap: 0.3rem;
     }
     .dl-checks li {
       font-family: var(--font-serif);
       font-size: 0.88rem;
       line-height: 1.5;
       color: var(--color-ink-light);
       padding-left: 1.3rem;
       position: relative;
     }
     .dl-checks li::before {
       content: "✓";
       position: absolute;
       left: 0;
       color: var(--color-sage);
       font-family: var(--font-typewriter);
       font-size: 0.8rem;
     }
     .dl-card-soon {
       background: var(--color-paper);
     }
     .dl-releases {
       list-style: none;
       margin: 0.5rem 0 1rem;
       padding: 0;
       display: grid;
       gap: 1rem;
     }
     .dl-release-head {
       margin: 0;
       font-family: var(--font-typewriter);
       font-size: 0.78rem;
       letter-spacing: 0.1em;
       color: var(--color-ink);
     }
     .dl-release-head span {
       color: var(--color-ink-muted);
     }
     .dl-waitlist-form {
       display: flex;
       flex-wrap: wrap;
       gap: 0.4rem;
       margin-top: 0.2rem;
     }
     .dl-waitlist-input {
       flex: 1 1 9rem;
       min-width: 0;
       padding: 0.42rem 0.6rem;
       font-family: var(--font-serif);
       font-size: 0.85rem;
       color: var(--color-ink);
       background: var(--color-paper-soft);
       border: 1px solid var(--color-paper-3);
       border-radius: 2px;
     }
     .dl-waitlist-input:focus {
       outline: none;
       border-color: var(--color-vermilion);
     }
     .dl-joined {
       font-family: var(--font-serif);
       font-size: 0.85rem;
       font-style: italic;
       color: var(--color-sage);
       margin: 0.2rem 0 0;
     }
     .dl-waitlist-error {
       font-family: var(--font-typewriter);
       font-size: 0.72rem;
       color: var(--color-vermilion);
       margin: 0.1rem 0 0;
     }
   `);

   return (
     <LegalPage
       title="Downloads"
       lead="Take Twyne to your own desk — or keep it in the browser."
       toc={[
         { id: "desktop", label: "Desktop app" },
         { id: "mobile", label: "Mobile apps" },
         { id: "web", label: "Web & install" },
         { id: "your-data", label: "Your data travels with you" },
         { id: "release-notes", label: "Release notes" },
       ]}
     >
       <div class="doc-callout">
         <p>
           The desktop app is a thin native shell around the live workspace at
           twyne.love — sync, hosted AI, publishing, and sign-in all behave the
           same as the web. Pick a platform below, or simply keep writing in your
           browser. Either way, your local-first folios stay yours.
         </p>
       </div>

       <h2 id="desktop" class="doc-h2">
         Desktop app
       </h2>
       <p class="doc-p">
         Native builds for macOS, Windows, and Linux. Each download is published
         with the release and served from this site, and opens Twyne in its own
         window. A few reasons it's worth the extra click over a browser tab:
       </p>

       <ul class="dl-benefits">
         <li>
           Distraction-free — a native window with no tabs, address bar, or
           browser chrome around your writing.
         </li>
         <li>
           Smoother ATProto sign-in — the app registers a <code>twyne://</code>{" "}
           URL scheme so OAuth callbacks land back in the app directly, instead
           of bouncing through a browser redirect.
         </li>
         <li>
           Its own dock or taskbar icon and app-switcher entry, separate from
           whatever else is open in your browser.
         </li>
         <li>
           The same account, sync, and hosted AI as the web — nothing to
           reconfigure when you move between desktop and browser.
         </li>
       </ul>

       <p
         class={`dl-detect-line ${detecting.value ? "" : "dl-detect-visible"}`}
         aria-live="polite"
       >
         {detected.value ? (
           <>
             Looks like you're on{" "}
             <strong>
               {PLATFORMS.find((p) => p.id === detected.value)?.name}
             </strong>
             — that card's stamped below.
           </>
         ) : (
           !detecting.value && "Pick your platform below."
         )}
       </p>

       <div class="dl-grid">
         {PLATFORMS.map((p) => (
           <div
             key={p.id}
             class={`dl-card ${detected.value === p.id ? "dl-card-recommended" : ""}`}
           >
             {detected.value === p.id && (
               <img
                 src="/approval-stamp.svg"
                 alt=""
                 class="dl-stamp stamp-tilt"
                 aria-hidden="true"
               />
             )}
             <span class="dl-glyph" aria-hidden="true">
-              {p.glyph}
+              <Icon name={p.icon} size={26} />
             </span>
             <span class="dl-name">{p.name}</span>
             <span class="dl-format">{p.format}</span>
             <p class="dl-note">{p.note}</p>
             <a class="dl-btn" href={p.href}>
               Download for {p.name}
             </a>
           </div>
         ))}
       </div>

       <p class="doc-p">
         Builds are unsigned for now, so your operating system may ask you to
         confirm before launching an app from an unidentified developer. The
         desktop shell never bundles your writing — it loads the same hosted
         workspace you use on the web.
       </p>

       <h2 id="mobile" class="doc-h2">
         Mobile apps
       </h2>
       <p class="doc-p">
         iOS and Android apps are in the works. Leave your email and we'll let
         you know the day they land — no spam, just one message when it's ready.
       </p>

       <div class="dl-grid">
         {mobileWaitlistCard({
           platform: MOBILE_PLATFORMS[0],
           email: iosEmail,
           status: iosStatus,
           error: iosError,
           onSubmit: submitIos,
         })}
         {mobileWaitlistCard({
           platform: MOBILE_PLATFORMS[1],
           email: androidEmail,
           status: androidStatus,
           error: androidError,
           onSubmit: submitAndroid,
         })}
       </div>

       <h2 id="web" class="doc-h2">
         Web &amp; install
       </h2>
       <p class="doc-p">
         No download required. Twyne runs in any modern browser and can be
         installed as a Progressive Web App for a standalone window, dock icon,
         and offline-friendly local-first storage.
       </p>

       <div class="dl-web">
         <div class="dl-web-body">
           <span class="dl-name">Open in the browser</span>
           <p>
             Visit Twyne and start writing immediately — no account needed. To
             install, use your browser's “Install app” or “Add to Home Screen”
             option from the address bar or menu.
           </p>
         </div>
         <a class="dl-btn" href="/">
           Launch Twyne
         </a>
       </div>

       <h2 id="your-data" class="doc-h2">
         Your data travels with you
       </h2>
       <ul class="dl-checks">
         <li>
           Local-first by default — your brief, folios, and drafts live in your
           browser's IndexedDB until you choose to sync.
         </li>
         <li>
           Sign in on any build to sync the same projects across desktop and web.
         </li>
         <li>
           Bring your own AI key, or use hosted AI — both work identically across
           platforms.
         </li>
         <li>
           Export any folio as Markdown, HTML, text, or a .twyne.json backup, on
           any device.
         </li>
       </ul>

       <h2 id="release-notes" class="doc-h2">
         Release notes
       </h2>
       {RELEASE_NOTES.length > 0 ? (
         <ol class="dl-releases">
           {RELEASE_NOTES.map((release) => (
             <li key={release.version} class="dl-release">
               <p class="dl-release-head">
                 <strong>{release.version}</strong>
                 {release.date && <span> · {release.date}</span>}
               </p>
               {release.highlights.length > 0 && (
                 <ul class="dl-checks">
                   {release.highlights.map((highlight) => (
                     <li key={highlight}>{highlight}</li>
                   ))}
                 </ul>
               )}
             </li>
           ))}
         </ol>
       ) : (
         <p class="doc-p">
           Fresh out of the press room — notes for the latest release will appear
           here.
         </p>
       )}
       <p class="doc-p">
         Questions about a build can go to{" "}
         <a href="mailto:support@twyne.love">support@twyne.love</a>.
       </p>
     </LegalPage>
   );
 });

 export const head: DocumentHead = {
   title: "Downloads · Twyne",
   meta: [
     {
       name: "description",
       content:
         "Download Twyne for macOS, Windows, and Linux, join the iOS/Android waitlist, or install the web app as a PWA. Local-first writing that syncs across every device.",
     },
   ],
 };

